DECOMPOSITION_TYPES: tuple[str, ...] = ("none", "shape", "intensity", "mixed",
                                        "uncertain")


def paired_defaults() -> dict[str, Any]:
    """대응 배선·이중 교정의 기본 설정. 값은 출발점이며 최적값이 아니다."""
    return {
        "wiring_mode": "legacy",
        "applied_mode": None,
        # --- 대응 관계 (명세 6.2): 우연한 거리 근접이 아니라 명시적 정수 인덱스 맵 ---
        "l2_l3_assignment": "linear_sum_assignment_on_surface_uv",
        "interareal_assignment": "balanced_assignment_on_visual_field",
        "center_assignment": "linear_sum_assignment_on_visual_field",
        # --- 주변부 수렴 (명세 6.4) -------------------------------------
        "fanin": {
            "K0": 1.0, "c": 2.0, "r0_deg": 1.0, "K_min": 1, "K_max": 6,
            "candidate_radius_rf_multiplier": 2.0,
            # 국소 수용장 반경: 영역 rf_sigma x 배수 x (1 + r/r0). 주변부 수용장이
            # 넓어진다는 **모델 선택**이다. "fixed" 로 두면 편심도와 무관하다.
            "candidate_radius_mode": "scaled_by_eccentricity",
            "boundary": "clip_to_available_candidates",
            "channel_rule": ("same_area_L4_spiny_stellate; nearest visual-field "
                             "distance; ties by neuron id; center input always kept"),
            "budget_mode": "summed",
        },
        "w0_median_nS": {"L4->L2": 2.6, "L2->L3": 2.6, "L3->L4": 3.0},
        "keep_lateral_recurrent": True,
        "disable_bypass": True,
        "decoder_layers": ["L3"],
        "rule_changes": [],
        # --- 이중 교정 (명세 8~12절) -------------------------------------
        "feedback": {
            "condition": "sequential_dual",
            "beta": 0.2, "beta_by_area": {},
            "deadband": 0.02,
            "teacher_gate_rule": "argmax_wrong",
            "max_iterations": 2,
            "kappa_shape_mV": 0.5, "kappa_intensity_mV": 0.5,
            "error_scale": 0.1, "eta_commit": 0.1,
            "target_clip": [0.0, 1.0],
            "decomposition": {
                "grouping": "surface_tiles", "tile_mm": 0.8, "eps_norm": 1e-6,
                "intensity_dominant_fraction": 0.8,
                "shape_dominant_fraction": 0.2,
            },
            "l3_to_l2_projection": "restorer_difference",
            "confidence_mode": "restorer_reliability",
            "constant_confidence": 0.5,
            "attention_alpha_for_attention_only": 0.5,
            "restorer": {"kind": "learned_linear", "epochs": 20, "eta": 0.05,
                         "max_fanout": 64},
            "record_provenance": True,
        },
        "note_ko": ("이 역할 배정은 검증할 **계산 가정**이다. 실제 피질의 L3 가 명암만 "
                    "처리하거나 L5/L6 가 이 수식을 계산한다는 확립된 사실이 아니다."),
    }


def engine_model_defaults() -> dict[str, Any]:
    return {
        "kind": "reference_multicompartment",
        "exact_lif": {
            "synapse_model": "current_based_fixed_driving_force",
            "driving_force_reference": "E_L_soma",
            "dendrites": "collapsed_to_soma",
            "threshold_crossing_time": "step_end (t_n+1), 구간 내 통과 시각 보간 없음",
        },
        "note_ko": ("single_compartment_exact_lif 는 기존 다구획 전도도 엔진과 **다른 "
                    "모델**이다. 결과·해시·체크포인트를 엔진별로 구분한다."),
    }


def _paired_rule(name: str, src: dict[str, Any], dst: dict[str, Any], *,
                 w_med: float, map_kind: str, meta: dict[str, Any],
                 delay: float = 0.9, vel: float = 0.2) -> dict[str, Any]:
    return {"name": name, "enabled": True, "src": src, "dst": dst,
            "target_compartment": "basal", "receptor": "AMPA",
            "selection": "paired_map", "k": 0, "probability": 1.0,
            "w0_median_nS": float(w_med), "w0_sigma": 0.3, "w0_max_nS": 24.0,
            "conduction_velocity_mm_per_ms": float(vel),
            "synaptic_delay_ms": float(delay), "gabor_initialized": False,
            "main_sensory_path": True,
            "paired": {"map": map_kind, **meta},
            "note": "주 감각 경로: 명시적 정수 인덱스 맵 (거리 우연 근접 아님)"}


def configure_paired(cfg: dict[str, Any], mode: str, *,
                     fanin: dict[str, Any] | None = None,
                     budget_mode: str | None = None) -> dict[str, Any]:
    """배선 모드를 적용한다. ``legacy`` 면 규칙을 **전혀** 바꾸지 않는다.

    대응 모드에서는 주 감각 경로를 ``L4 -> L2 -> L3 -> 다음 영역 L4`` 로 바꾼다.

    * 기존 ``{A}_L4->L2L3`` (L4 가 L2 와 L3 양쪽에 직접 입력) 을 끈다.
    * 기존 ``{A}->{B}_FF`` (L2 와 L3 양쪽이 다음 영역에 출력) 를 끈다.
    * ``disable_bypass`` 면 영역을 건너뛰는 우회 FF (예: V1->V4) 를 끈다.
    * 새 규칙은 목록 **끝에** 붙인다. 기존 규칙의 인덱스가 그대로라 배선·가중치
      난수 스트림이 legacy 와 같다 (감각 이외 연결의 배치를 맞추기 위해서다).

    끈 규칙과 추가한 규칙은 ``cfg['paired']['rule_changes']`` 에 남는다.
    """
    if mode not in PAIRED_WIRING_MODES:
        raise ValueError(f"알 수 없는 배선 모드: {mode!r} (가능: {list(PAIRED_WIRING_MODES)})")
    pc = cfg.setdefault("paired", paired_defaults())
    if pc.get("applied_mode") not in (None, mode):
        raise ValueError(
            f"이미 배선 모드 {pc['applied_mode']!r} 가 적용된 설정이다. 새 설정에서 "
            f"다시 만들어라 (두 모드를 겹쳐 적용하지 않는다).")
    if fanin:
        pc["fanin"].update(fanin)
    if budget_mode is not None:
        pc["fanin"]["budget_mode"] = str(budget_mode)
    pc["wiring_mode"] = mode
    if pc.get("applied_mode") == mode:
        return cfg
    pc["applied_mode"] = mode
    if mode == "legacy":
        pc["rule_changes"] = [{"action": "none",
                               "note_ko": "legacy: 3.2.2 배선 규칙을 그대로 쓴다"}]
        return cfg
    rules = cfg["wiring"]["rules"]
    areas = cfg["areas"]
    cortex = sorted((a for a, v in areas.items() if v["kind"] == "cortex"),
                    key=lambda a: areas[a]["level"])
    chain = list(zip(cortex[:-1], cortex[1:]))
    changes: list[dict[str, Any]] = []
    main_ff = {f"{a}->{b}_FF" for a, b in chain}
    for r in rules:
        name = r["name"]
        reason = None
        if name.endswith("_L4->L2L3") and r["src"]["area"] in cortex:
            reason = "L4 가 L2/L3 양쪽에 주 입력을 직접 보내던 규칙 (L4->L2->L3 로 대체)"
        elif name.endswith("_FF") and name in main_ff:
            reason = "L2/L3 양쪽이 다음 영역에 주 출력을 보내던 규칙 (L3->다음 L4 로 대체)"
        elif name.endswith("_FF") and pc.get("disable_bypass", True):
            reason = "영역을 건너뛰는 우회 FF. 숨은 우회로 전달 성공을 만들지 않는다"
        if reason is not None and r.get("enabled", True):
            r["enabled"] = False
            r["disabled_by"] = f"paired:{mode}"
            changes.append({"action": "disabled", "rule": name, "reason_ko": reason})
        elif name.endswith("_L2L3_lateral"):
            if not pc.get("keep_lateral_recurrent", True):
                r["enabled"] = False
                r["disabled_by"] = f"paired:{mode}"
                changes.append({"action": "disabled", "rule": name,
                                "reason_ko": "재귀 측방 연결 끔 (대조 설정)"})
            else:
                r["connection_class"] = "recurrent_lateral_not_main_path"
                changes.append({"action": "kept_as_separate_group", "rule": name,
                                "reason_ko": ("L2<->L3 재귀 측방 연결은 주 전달 경로와 "
                                              "다른 연결군으로 유지한다")})
    fan = dict(pc["fanin"])
    if mode == "paired_only":
        fan.update(c=0.0, K0=1.0, K_min=1, K_max=1)
    w = pc["w0_median_nS"]
    exc = {"cell_types": ["pyramidal"]}
    for a in cortex:
        rules.append(_paired_rule(
            f"{a}_L4->L2_paired",
            {"area": a, "layers": ["L4"], "cell_types": ["spiny_stellate"]},
            {"area": a, "layers": ["L2"], **exc},
            w_med=w["L4->L2"], map_kind="L4_to_L2_fanin",
            meta={"area": a, "fanin": fan, "calibration_basis": "center_edges"}))
        rules.append(_paired_rule(
            f"{a}_L2->L3_paired",
            {"area": a, "layers": ["L2"], **exc},
            {"area": a, "layers": ["L3"], **exc},
            w_med=w["L2->L3"], map_kind="L2_to_L3_one_to_one",
            meta={"area": a, "calibration_basis": "all_edges"}))
        changes.append({"action": "added", "rule": f"{a}_L4->L2_paired",
                        "reason_ko": f"L4->L2 수렴 연결 ({mode})"})
        changes.append({"action": "added", "rule": f"{a}_L2->L3_paired",
                        "reason_ko": "L2 슬롯 k -> L3 슬롯 k 일대일"})
    for a, b in chain:
        lvl = abs(areas[b]["level"] - areas[a]["level"])
        rules.append(_paired_rule(
            f"{a}_L3->{b}_L4_paired",
            {"area": a, "layers": ["L3"], **exc},
            {"area": b, "layers": ["L4"], "cell_types": ["spiny_stellate"]},
            w_med=w["L3->L4"], map_kind="L3_to_next_L4",
            meta={"src_area": a, "dst_area": b, "calibration_basis": "all_edges"},
            delay=2.0 + 0.4 * lvl, vel=0.5))
        changes.append({"action": "added", "rule": f"{a}_L3->{b}_L4_paired",
                        "reason_ko": "L3 출력 슬롯 -> 다음 영역 L4 수신 슬롯"})
    want = list(pc.get("decoder_layers") or ["L3"])
    dec_area = cfg["decoder"]["area"]
    n_exc = sum(_expected_cell_count(cfg, dec_area, lay, ct)
                for lay in want for ct in cfg["decoder"]["cell_types"])
    if n_exc >= len(cfg["decoder"]["classes"]):
        cfg["decoder"]["layers"] = want
        changes.append({"action": "decoder_layers", "value": want,
                        "reason_ko": "IT 의 주 출력은 L3 이다 (고정 해독기도 L3 만 읽는다)"})
    else:
        changes.append({"action": "decoder_layers_kept", "value": cfg["decoder"]["layers"],
                        "reason_ko": (f"{dec_area} {want} 흥분성 세포 {n_exc}개 < 클래스 "
                                      f"{len(cfg['decoder']['classes'])}개라 기존 고정 해독기는 "
                                      "L2+L3 를 그대로 읽는다. 이중 교정의 분류기 C 는 L3 "
                                      "슬롯만 읽는다.")})
    cfg["wiring"]["graph_feedforward"] = [list(e) for e in chain]
    pc["rule_changes"] = changes
    return cfg


def _expected_cell_count(cfg: dict[str, Any], area: str, layer: str, cell: str) -> int:
    """빌더와 같은 규칙(비율 반올림, 부족분은 첫 유형으로 채움)으로 세포 수를 센다."""
    spec = cfg["areas"][area]
    count = int(spec["neurons_per_layer"].get(layer, 0))
    fr = spec["cell_type_fractions"].get(layer, {})
    types: list[str] = []
    for ct, f in sorted(fr.items()):
        types += [ct] * int(round(float(f) * count))
    while len(types) < count and fr:
        types.append(sorted(fr)[0])
    return types[:count].count(cell)


# ----------------------------------------------------------------------
# 백엔드 중립 계산 (NumPy 배열과 torch 텐서 모두에서 같은 식으로 동작한다)
# ----------------------------------------------------------------------
def _is_torch(x: Any) -> bool:
    return torch is not None and isinstance(x, torch.Tensor)


def _xsum(x: Any, axis: int, keepdims: bool = False) -> Any:
    if _is_torch(x):
        return x.sum(dim=axis, keepdim=keepdims)
    return np.sum(x, axis=axis, keepdims=keepdims)


def _xclip(x: Any, lo: float | None, hi: float | None) -> Any:
    if _is_torch(x):
        return torch.clamp(x, min=lo, max=hi)
    return np.clip(x, lo, hi)


def _xwhere(cond: Any, a: Any, b: Any) -> Any:
    if _is_torch(cond) or _is_torch(a) or _is_torch(b):
        return torch.where(cond, a, b)
    return np.where(cond, a, b)


def _xabs(x: Any) -> Any:
    return x.abs() if _is_torch(x) else np.abs(x)


def _xsqrt(x: Any) -> Any:
    return torch.sqrt(x) if _is_torch(x) else np.sqrt(x)


def _xzeros_like(x: Any) -> Any:
    return torch.zeros_like(x) if _is_torch(x) else np.zeros_like(x)


def _xany_last(x: Any) -> Any:
    return x.any(dim=-1) if _is_torch(x) else np.any(x, axis=-1)


def fanin_k(ecc_deg: Any, *, K0: float, c: float, r0_deg: float, K_min: int,
            K_max: int) -> np.ndarray:
    """``K(r) = clip(round(K0 + c*log(1 + r/r0)), K_min, K_max)`` (명세 6.4).

    ``r`` 은 **원본 시야 중심으로부터의 편심도(deg)** 다. 피질 XYZ 거리가 아니다.
    ``c = 0`` 이면 모든 위치에서 ``round(K0)`` (대응 대조군).
    """
    r = np.asarray(ecc_deg, dtype=np.float64)
    if r0_deg <= 0:
        raise ValueError("r0_deg 는 양수여야 한다")
    if not (1 <= int(K_min) <= int(K_max)):
        raise ValueError("1 <= K_min <= K_max 여야 한다")
    if np.any(r < 0) or not np.all(np.isfinite(r)):
        raise ValueError("편심도는 유한한 비음수다")
    k = np.rint(float(K0) + float(c) * np.log1p(r / float(r0_deg)))
    return np.clip(k, int(K_min), int(K_max)).astype(np.int64)


def correction_needed(masked_error: Any, deadband: float) -> Any:
    """마스크를 적용한 **실제** 교정 벡터에 허용 범위를 넘는 성분이 있는가 (명세 8절).

    합이 0 인지를 보지 않는다. 양수와 음수가 합쳐져 0 이 되는 벡터도 교정이 필요하다.
    """
    return _xany_last(_xabs(masked_error) > float(deadband))


def dtp_lower_error(restore: Callable[[Any], Any], h_upper: Any, target_upper: Any,
                    beta: float, gate: Any) -> tuple[Any, Any]:
    """``e_B = beta * (D_A(h_A) - D_A(target_A))`` 와 복원 기본 오차를 분리한다.

    * 두 ``D_A`` 호출은 **같은 함수 객체**(같은 가중치·상태)를 쓴다.
    * gate 가 꺼진 표본은 ``target_A`` 대신 ``h_A`` 를 넣는다. 같은 입력의 같은 연산
      결과는 비트 단위로 같으므로 ``e_B`` 가 정확히 0 이 된다. 그 위에 gate 를 다시
      곱해 부동소수 잔차가 끼어들 여지를 없앤다.
    * ``beta = 0`` 이면 정확히 0 이다.

    Returns ``(e_B, D_A(h_A))``. 기본 복원 오차 ``h_B - D_A(h_A)`` 는 호출한 쪽이
    **지표로만** 계산하며 교사 오차에 더하지 않는다.
    """
    g = gate
    if _is_torch(g):
        g = g.to(h_upper.dtype)
    else:
        g = np.asarray(g, dtype=np.float64)
    while g.ndim < h_upper.ndim:
        g = g[..., None]
    t_eff = _xwhere(g > 0, target_upper, h_upper)
    d_h = restore(h_upper)
    d_t = restore(t_eff)
    if float(beta) == 0.0:
        return _xzeros_like(d_h), d_h
    e = float(beta) * (d_h - d_t) * g
    return e, d_h


def amplitude_pattern_decompose(activity: Any, error: Any, groups: Sequence[Any], *,
                                eps: float) -> dict[str, Any]:
    """활동 패턴 크기 성분과 패턴 성분으로 교정을 나눈다 (명세 10.2 의 공학적 기본 대조).

    그룹 g 마다 ``v = a_g/||a_g||``, ``e_int = v (v·e_g)``, ``e_pat = e_g - e_int``.
    ``||a_g|| <= eps`` 이면 방향을 정할 수 없으므로 ``e_int = 0``, ``e_pat = e_g`` 로
    두고 그 그룹을 ``uncertain`` 으로 표시한다 (교정을 조용히 버리지 않는다).

    ``e_int`` 는 **그 활동 패턴의 크기 변화**(activity_amplitude_proxy) 일 뿐이며 실제
    영상 명도 원인이라는 증명이 아니다. ``e_pat`` 은 pattern_proxy 다.

    ``activity``/``error`` 는 ``[..., n]``. ``groups`` 는 슬롯 인덱스 배열의 목록이며
    서로 겹치지 않고 전체를 덮어야 한다.
    """
    e_int = _xzeros_like(error)
    inactive = _xzeros_like(error)
    for g in groups:
        a = activity[..., g]
        e = error[..., g]
        norm = _xsqrt(_xsum(a * a, -1, keepdims=True))
        ok = norm > float(eps)
        safe = _xwhere(ok, norm, norm * 0 + 1.0)
        v = a / safe
        proj = _xsum(v * e, -1, keepdims=True)
        part = _xwhere(ok, v * proj, e * 0)
        e_int[..., g] = part
        inactive[..., g] = _xwhere(ok, e * 0, e * 0 + 1.0)
    e_pat = error - e_int
    residual = _xabs(error - (e_int + e_pat))
    n_el = residual.numel() if _is_torch(residual) else residual.size
    return {"intensity": e_int, "pattern": e_pat, "inactive_mask": inactive,
            "sum_residual_max": float(residual.max()) if n_el else 0.0,
            "labels": {"intensity": "activity_amplitude_proxy",
                       "pattern": "pattern_proxy"}}


def classify_decomposition(error: Any, intensity: Any, inactive: Any,
                           groups: Sequence[Any], *, tol: float, hi: float,
                           lo: float) -> list[dict[str, Any]]:
    """그룹별 유형 판정. 확률이 아니라 에너지 비율의 **여유(margin)** 를 쓴다.

    ``f_int = ||e_int||^2 / ||e||^2``. ``||e||_inf <= tol`` 이면 ``none``, 비활성
    그룹이면 ``uncertain``, ``f_int >= hi`` 면 ``intensity``, ``f_int <= lo`` 면
    ``shape``, 사이면 ``mixed``. ``decomposition_margin = |2 f_int - 1|`` 은 두 성분이
    얼마나 한쪽으로 치우쳤는지를 뜻하며 **원인 확률이 아니다.**

    ``error`` 등은 한 표본의 ``[n]`` 벡터(NumPy 또는 CPU 로 옮긴 값)다.
    """
    out: list[dict[str, Any]] = []
    e_all = np.asarray(error, dtype=np.float64)
    i_all = np.asarray(intensity, dtype=np.float64)
    m_all = np.asarray(inactive, dtype=np.float64)
    for gi, g in enumerate(groups):
        idx = np.asarray(g, dtype=np.int64)
        e = e_all[idx]
        ei = i_all[idx]
        en = float(np.sum(e * e))
        if idx.size == 0 or float(np.max(np.abs(e), initial=0.0)) <= tol:
            kind, f, margin = "none", None, None
        elif float(np.max(m_all[idx], initial=0.0)) > 0:
            kind, f, margin = "uncertain", None, None
        else:
            f = float(np.sum(ei * ei) / en) if en > 0 else 0.0
            margin = abs(2.0 * f - 1.0)
            kind = ("intensity" if f >= hi else "shape" if f <= lo else "mixed")
        out.append({"group": gi, "n": int(idx.size), "type": kind,
                    "intensity_energy_fraction": f,
                    "decomposition_margin": margin,
                    "error_l2": math.sqrt(en)})
    return out


def exact_lif_coefficients(tau_ms: Any, dt_ms: float) -> tuple[Any, Any]:
    """고정 dt/tau 의 ``alpha = exp(-dt/tau)`` 와 ``1 - alpha`` (초기화 때 한 번)."""
    if _is_torch(tau_ms):
        alpha = torch.exp(-float(dt_ms) / tau_ms)
    else:
        alpha = np.exp(-float(dt_ms) / np.asarray(tau_ms, dtype=np.float64))
    return alpha, 1.0 - alpha


def exact_lif_update(u: Any, s: Any, alpha: Any, one_minus_alpha: Any) -> Any:
    """``tau du/dt = -u + s`` 의 구간 상수 입력 정확해: ``u' = alpha u + (1-alpha) s``.

    ``u`` 는 안정 전위에서의 편차 [mV], ``s`` 도 같은 전압 척도 [mV] (``R*I``).
    임계값 판정·리셋·불응기·지연은 이 함수 밖에서 따로 처리한다.
    """
    return alpha * u + one_minus_alpha * s


# ----------------------------------------------------------------------
# 슬롯 계획기 (NumPy 전용: 배선 생성 시 한 번 계산하고 기록한다)
# ----------------------------------------------------------------------
def _assign(cost: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """직사각형 최소 비용 할당. 작은 쪽의 모든 원소가 정확히 한 번 쓰인다."""
    from scipy.optimize import linear_sum_assignment
    if cost.size == 0:
        return np.zeros(0, np.int64), np.zeros(0, np.int64)
    r, c = linear_sum_assignment(cost)
    order = np.argsort(r, kind="stable")
    return r[order].astype(np.int64), c[order].astype(np.int64)


def balanced_bipartite_map(cost: np.ndarray) -> np.ndarray:
    """모든 행과 모든 열이 **최소 한 번** 쓰이는 결정론적 대응 쌍 ``[(row, col), ...]``.

    1단계: 직사각형 할당으로 작은 쪽 전체를 덮는다.
    2단계: 큰 쪽의 남은 원소를 작은 쪽에 용량 ``ceil(max/min)-1`` 로 추가 할당한다.
    그래서 작은 쪽 원소 하나가 받는 짝의 수는 1 이상 ``ceil(max/min)`` 이하다.
    """
    n_r, n_c = cost.shape
    if n_r == 0 or n_c == 0:
        return np.zeros((0, 2), np.int64)
    r1, c1 = _assign(cost)
    pairs = [np.stack([r1, c1], axis=1)]
    if n_r > n_c:
        rest = np.setdiff1d(np.arange(n_r), r1)
        cap = int(math.ceil(n_r / n_c)) - 1
        if rest.size:
            tiled = np.tile(cost[rest], (1, cap))              # [rest, n_c*cap]
            r2, c2 = _assign(tiled)
            pairs.append(np.stack([rest[r2], c2 % n_c], axis=1))
    elif n_c > n_r:
        rest = np.setdiff1d(np.arange(n_c), c1)
        cap = int(math.ceil(n_c / n_r)) - 1
        if rest.size:
            tiled = np.tile(cost[:, rest].T, (1, cap))         # [rest, n_r*cap]
            r2, c2 = _assign(tiled)
            pairs.append(np.stack([c2 % n_r, rest[r2]], axis=1))
    out = np.concatenate(pairs, axis=0)
    order = np.lexsort((out[:, 0], out[:, 1]))
    return out[order]


def _csr_from_pairs(dst_index: np.ndarray, src_index: np.ndarray,
                    n_dst: int) -> tuple[np.ndarray, np.ndarray]:
    order = np.lexsort((src_index, dst_index))
    d, s = dst_index[order], src_index[order]
    indptr = np.zeros(n_dst + 1, dtype=np.int64)
    np.add.at(indptr, d + 1, 1)
    return np.cumsum(indptr), s.astype(np.int64)


def _vf_cost(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    return np.sqrt(((a[:, None, :] - b[None, :, :]) ** 2).sum(axis=2))


class PairedSlotPlanner:
    """주 감각 경로의 **정수 인덱스 맵**을 만든다 (명세 6.2~6.4).

    * 슬롯은 흥분성 주 신호 채널이다. 영역의 전체 세포 수(PV/SST 포함)와 다르다.
    * L2 슬롯 순서는 뉴런 ID 오름차순이다. L3 슬롯 k 는 L2 슬롯 k 의 짝이다
      (표면 좌표 최소 비용 할당으로 한 번 정해 저장한다).
    * L4 -> L2: L2 슬롯마다 중심 L4 하나(할당) + 편심도에 따라 K(r)-1 개의 추가 L4
      (국소 수용장 안 최근접, 동점은 ID 순). seed 로 정하는 전역 무작위 연결이 아니다.
    * L3(A) -> L4(B): 모든 L3 와 모든 L4 가 최소 한 번 쓰이는 균형 대응. 개수가
      다르면 일대다/다대일로 **명시**한다.
    """

    def __init__(self, cfg: dict[str, Any], meta_np: dict[str, np.ndarray],
                 area_names: Sequence[str], layer_names: Sequence[str],
                 cell_type_names: Sequence[str],
                 sampler_grid: tuple[np.ndarray, np.ndarray, np.ndarray] | None = None
                 ) -> None:
        self.cfg = cfg
        self.m = meta_np
        self.area_names = list(area_names)
        self.layer_names = list(layer_names)
        self.cell_type_names = list(cell_type_names)
        self.sampler_grid = sampler_grid
        self._areas: dict[str, dict[str, Any]] = {}
        self._inter: dict[str, dict[str, Any]] = {}
        #: 영역별 수렴 설정은 **규칙에 저장된 값**을 쓴다 (설정 해시에 포함된다).
        self._fan_by_area: dict[str, dict[str, Any]] = {}
        for r in cfg["wiring"]["rules"]:
            p = r.get("paired") or {}
            if r.get("enabled", True) and p.get("map") == "L4_to_L2_fanin":
                self._fan_by_area[str(p["area"])] = dict(p["fanin"])

    # -- 선택 ----------------------------------------------------------
    def _ids(self, area: str, layer: str, cell: str) -> np.ndarray:
        m = self.m
        if area not in self.area_names or layer not in self.layer_names \
                or cell not in self.cell_type_names:
            return np.zeros(0, np.int64)
        mask = ((m["aid"] == self.area_names.index(area))
                & (m["lid"] == self.layer_names.index(layer))
                & (m["cid"] == self.cell_type_names.index(cell)))
        return np.nonzero(mask)[0].astype(np.int64)

    def area_plan(self, area: str, fan: dict[str, Any] | None = None) -> dict[str, Any]:
        if area in self._areas:
            return self._areas[area]
        m = self.m
        l4 = self._ids(area, "L4", "spiny_stellate")
        l2 = self._ids(area, "L2", "pyramidal")
        l3_all = self._ids(area, "L3", "pyramidal")
        # --- L2 <-> L3 일대일 ---------------------------------------
        cost = _vf_cost(m["uv"][l2], m["uv"][l3_all]) if l2.size and l3_all.size \
            else np.zeros((l2.size, l3_all.size))
        r, c = _assign(cost)
        paired_l2 = l2[r]
        paired_l3 = l3_all[c]
        unpaired_l2 = np.setdiff1d(l2, paired_l2)
        unpaired_l3 = np.setdiff1d(l3_all, paired_l3)
        l2_slots = np.concatenate([paired_l2, unpaired_l2])
        l3_slots = np.concatenate([paired_l3, unpaired_l3])
        # --- L4 -> L2 중심 + 수렴 ------------------------------------
        fan = dict(fan or self._fan_by_area.get(area) or self.cfg["paired"]["fanin"])
        vf = m["vf"]
        ecc = np.sqrt((vf[l2_slots] ** 2).sum(axis=1)) if l2_slots.size else np.zeros(0)
        k_req = fanin_k(ecc, K0=float(fan["K0"]), c=float(fan["c"]),
                        r0_deg=float(fan["r0_deg"]), K_min=int(fan["K_min"]),
                        K_max=int(fan["K_max"])) if l2_slots.size else np.zeros(0, np.int64)
        center = np.full(l2_slots.size, -1, dtype=np.int64)
        if l4.size and l2_slots.size:
            ccost = _vf_cost(vf[l4], vf[l2_slots])              # [nL4, nL2]
            if l4.size >= l2_slots.size:
                rr, cc = _assign(ccost)
                center[cc] = rr
            else:
                pairs = balanced_bipartite_map(ccost)
                for i, j in pairs:
                    if center[j] < 0:
                        center[j] = i
        rf_area = float(self.cfg["areas"][area]["rf_sigma_deg"])
        base_radius = float(fan["candidate_radius_rf_multiplier"]) * rf_area
        radius_mode = str(fan.get("candidate_radius_mode", "fixed"))
        if radius_mode not in ("fixed", "scaled_by_eccentricity"):
            raise ValueError(f"알 수 없는 candidate_radius_mode: {radius_mode!r}")
        radii = (base_radius * (1.0 + ecc / float(fan["r0_deg"]))
                 if radius_mode == "scaled_by_eccentricity"
                 else np.full(ecc.shape, base_radius))
        src_lists: list[np.ndarray] = []
        k_act = np.zeros(l2_slots.size, dtype=np.int64)
        truncated = 0
        eff_rf = np.zeros(l2_slots.size)
        for j in range(l2_slots.size):
            if center[j] < 0:
                src_lists.append(np.zeros(0, np.int64))
                continue
            chosen = [int(center[j])]
            need = int(k_req[j]) - 1
            if need > 0:
                d = np.sqrt(((vf[l4] - vf[l2_slots[j]]) ** 2).sum(axis=1))
                order = np.lexsort((l4, d))
                cand = [int(i) for i in order
                        if int(i) != int(center[j]) and d[int(i)] <= radii[j]]
                chosen += cand[:need]
                if len(cand) < need:
                    truncated += 1
            arr = np.asarray(chosen, dtype=np.int64)
            src_lists.append(arr)
            k_act[j] = arr.size
            dist = np.sqrt(((vf[l4[arr]] - vf[l2_slots[j]]) ** 2).sum(axis=1))
            eff_rf[j] = float(np.max(dist + rf_area))
        dst_idx = np.concatenate([np.full(s.size, j, np.int64)
                                  for j, s in enumerate(src_lists)]) \
            if src_lists else np.zeros(0, np.int64)
        src_idx = np.concatenate(src_lists) if src_lists else np.zeros(0, np.int64)
        indptr, l4_slot = _csr_from_pairs(dst_idx, src_idx, l2_slots.size)
        used = np.zeros(l4.size, dtype=bool)
        used[l4_slot] = True
        pref = None
        if self.sampler_grid is not None and l2_slots.size:
            gx, gy, gs = self.sampler_grid
            d2 = ((vf[l2_slots][:, None, 0] - gx[None, :]) ** 2
                  + (vf[l2_slots][:, None, 1] - gy[None, :]) ** 2)
            pref = gs[np.argmin(d2, axis=1)]
        plan = {
            "area": area,
            "L4E": l4, "L2E": l2_slots, "L3E": l3_slots,
            "n_paired": int(paired_l2.size),
            "unpaired_L2": unpaired_l2, "unpaired_L3": unpaired_l3,
            "fanin_indptr": indptr, "fanin_l4_slot": l4_slot,
            "center_l4_slot": center, "center_edge": None,
            "K_requested": k_req, "K_actual": k_act, "ecc_deg": ecc,
            "n_truncated": int(truncated),
            "candidate_radius_mode": radius_mode,
            "candidate_radius_deg": radii,
            "effective_rf_radius_deg": eff_rf,
            "retinotopic_prefilter_sigma_deg": pref,
            "l4_slots_not_routed_to_L2": np.nonzero(~used)[0].astype(np.int64),
            "fanin": fan,
        }
        self._areas[area] = plan
        return plan

    def interareal_plan(self, src_area: str, dst_area: str) -> dict[str, Any]:
        key = f"{src_area}->{dst_area}"
        if key in self._inter:
            return self._inter[key]
        a = self.area_plan(src_area)
        b = self.area_plan(dst_area)
        l3 = a["L3E"]
        l4 = b["L4E"]
        vf = self.m["vf"]
        cost = _vf_cost(vf[l3], vf[l4]) if l3.size and l4.size else np.zeros((l3.size, l4.size))
        pairs = balanced_bipartite_map(cost)                   # (l3 slot, l4 slot)
        indptr, src_slot = _csr_from_pairs(pairs[:, 1], pairs[:, 0], l4.size)
        fan_in = np.diff(indptr)
        fan_out = np.bincount(pairs[:, 0], minlength=l3.size) if pairs.size \
            else np.zeros(l3.size, np.int64)
        if l3.size == l4.size:
            kind = "one_to_one"
        elif l3.size > l4.size:
            kind = "many_to_one"
        else:
            kind = "one_to_many"
        plan = {"src_area": src_area, "dst_area": dst_area,
                "n_src_slots": int(l3.size), "n_dst_slots": int(l4.size),
                "indptr": indptr, "src_l3_slot": src_slot,
                "pairs": pairs, "correspondence": kind,
                "fan_in_min": int(fan_in.min()) if fan_in.size else 0,
                "fan_in_max": int(fan_in.max()) if fan_in.size else 0,
                "fan_out_min": int(fan_out.min()) if fan_out.size else 0,
                "fan_out_max": int(fan_out.max()) if fan_out.size else 0,
                "note_ko": ("L3 출력 슬롯 수와 다음 L4 수신 슬롯 수가 다르면 일대일이 "
                            "아니다. 대응 쌍과 개수를 그대로 기록한다.")}
        self._inter[key] = plan
        return plan

    # -- 규칙 -> edge ------------------------------------------------------
    def edges_for(self, rule: dict[str, Any]) -> tuple[np.ndarray, np.ndarray,
                                                     np.ndarray, dict[str, Any]]:
        """``(src_ids, dst_ids, center_mask, info)``. 난수를 쓰지 않는다."""
        p = rule["paired"]
        kind = p["map"]
        if kind == "L4_to_L2_fanin":
            plan = self.area_plan(p["area"], p.get("fanin"))
            ip, l4s = plan["fanin_indptr"], plan["fanin_l4_slot"]
            dst_slot = np.repeat(np.arange(plan["L2E"].size), np.diff(ip))
            src = plan["L4E"][l4s]
            dst = plan["L2E"][dst_slot]
            center = l4s == plan["center_l4_slot"][dst_slot]
            info = {"map": kind, "n_dst_slots": int(plan["L2E"].size),
                    "K_mean": float(plan["K_actual"].mean()) if plan["K_actual"].size
                    else 0.0,
                    "K_max_actual": int(plan["K_actual"].max())
                    if plan["K_actual"].size else 0,
                    "n_truncated": plan["n_truncated"]}
            return src, dst, center, info
        if kind == "L2_to_L3_one_to_one":
            plan = self.area_plan(p["area"])
            n = plan["n_paired"]
            src = plan["L2E"][:n]
            dst = plan["L3E"][:n]
            return src, dst, np.ones(n, dtype=bool), {
                "map": kind, "n_pairs": int(n),
                "n_unpaired_L2": int(plan["unpaired_L2"].size),
                "n_unpaired_L3": int(plan["unpaired_L3"].size)}
        if kind == "L3_to_next_L4":
            plan = self.interareal_plan(p["src_area"], p["dst_area"])
            a = self.area_plan(p["src_area"])
            b = self.area_plan(p["dst_area"])
            src = a["L3E"][plan["pairs"][:, 0]]
            dst = b["L4E"][plan["pairs"][:, 1]]
            return src, dst, np.ones(src.size, dtype=bool), {
                "map": kind, "correspondence": plan["correspondence"],
                "n_src_slots": plan["n_src_slots"], "n_dst_slots": plan["n_dst_slots"]}
        raise ValueError(f"알 수 없는 paired map: {kind!r}")

    def slot_map(self) -> dict[str, Any]:
        """저장·조회용 슬롯 맵 (JSON 직렬화 가능). 해시를 함께 담는다."""
        def lst(x: Any) -> Any:
            return None if x is None else np.asarray(x).tolist()
        areas = {}
        for name, p in self._areas.items():
            areas[name] = {k: (lst(v) if isinstance(v, np.ndarray) else v)
                           for k, v in p.items()}
        inter = {}
        for key, p in self._inter.items():
            inter[key] = {k: (lst(v) if isinstance(v, np.ndarray) else v)
                          for k, v in p.items()}
        body = {"version": PAIRED_MAP_VERSION,
                "wiring_mode": self.cfg["paired"]["wiring_mode"],
                "areas": areas, "interareal": inter}
        body["hash"] = sha256_text(json.dumps(body, sort_keys=True,
                                              default=_json_default))
        return body


def _cortical_area(level: int, extent_mm: Sequence[float],
                   counts: dict[str, int], rf_sigma_deg: float,
                   layer_thickness_mm: dict[str, float] | None = None) -> dict[str, Any]:
    return {
        "kind": "cortex", "level": int(level),
        "surface_extent_mm": [float(extent_mm[0]), float(extent_mm[1])],
        "layer_thickness_mm": dict(layer_thickness_mm or {
            "L1": 0.10, "L2": 0.22, "L3": 0.33, "L4": 0.30, "L5": 0.38, "L6": 0.37}),
        "neurons_per_layer": dict(counts),
        "cell_type_fractions": {
            "L1": {"l1_inhibitory": 1.0},
            "L2": {"pyramidal": 0.72, "pv_basket": 0.18, "sst_martinotti": 0.10},
            "L3": {"pyramidal": 0.72, "pv_basket": 0.18, "sst_martinotti": 0.10},
            "L4": {"spiny_stellate": 0.80, "pv_basket": 0.20},
            "L5": {"pyramidal": 0.82, "pv_basket": 0.18},
            "L6": {"pyramidal": 0.85, "pv_basket": 0.15},
        },
        "rf_sigma_deg": float(rf_sigma_deg),
    }


def _v1_counts(scale: int) -> dict[str, int]:
    return {"L1": max(2, scale // 4), "L2": 2 * scale, "L3": 2 * scale,
            "L4": 3 * scale, "L5": scale, "L6": scale}


def _local_rules(area: str, scale: float = 1.0) -> list[dict[str, Any]]:
    """한 피질 영역 내부의 층간·억제·재귀 배선.

    층을 가로지르는 규칙은 **표면 접선 거리**(``radius_space='surface'``)로 후보를
    고른다. 깊이를 포함한 3D 거리로 재면 층 간격보다 작은 반경에서 후보가 하나도
    나오지 않아 이름만 있는 경로가 된다. 지연은 언제나 3D 직선 거리를 쓴다.
    """
    def rule(name, src_l, dst_l, *, comp="basal", receptor="AMPA", radius,
             space, k, prob, w_med, src_types=None, dst_types=None,
             vel=0.2, delay=0.8, note=""):
        return {"name": f"{area}_{name}", "enabled": True,
                "src": {"area": area, "layers": list(src_l),
                        "cell_types": list(src_types or [])},
                "dst": {"area": area, "layers": list(dst_l),
                        "cell_types": list(dst_types or [])},
                "target_compartment": comp, "receptor": receptor,
                "selection": "local_radius", "radius_mm": float(radius),
                "radius_space": space, "k": int(k), "probability": float(prob),
                "w0_median_nS": float(w_med * scale), "w0_sigma": 0.3,
                "w0_max_nS": float(8.0 * scale),
                "conduction_velocity_mm_per_ms": float(vel),
                "synaptic_delay_ms": float(delay),
                "gabor_initialized": False, "note": note}

    return [
        rule("L4->L2L3", ["L4"], ["L2", "L3"], radius=0.45, space="surface", k=8,
             prob=0.6, w_med=2.6, src_types=["spiny_stellate"],
             dst_types=["pyramidal"], note="L4 -> L2/3 상행"),
        rule("L4->L4_PV", ["L4"], ["L4"], comp="soma", radius=0.35, space="cortical_3d",
             k=6, prob=0.6, w_med=2.2, src_types=["spiny_stellate"],
             dst_types=["pv_basket"]),
        rule("L4_PV->L4", ["L4"], ["L4"], comp="soma", receptor="GABA_A",
             radius=0.35, space="cortical_3d", k=6, prob=0.65, w_med=2.0,
             src_types=["pv_basket"], dst_types=["spiny_stellate"],
             note="PV 는 soma 표적 억제"),
        rule("L2L3_lateral", ["L2", "L3"], ["L2", "L3"], radius=0.6,
             space="cortical_3d", k=6, prob=0.35, w_med=1.4,
             src_types=["pyramidal"], dst_types=["pyramidal"], vel=0.15, delay=1.4,
             note="수평 재귀 연결 (지연이 실제로 계산에 들어간다)"),
        rule("L2L3->PV", ["L2", "L3"], ["L2", "L3"], comp="soma", radius=0.5,
             space="cortical_3d", k=5, prob=0.5, w_med=2.0,
             src_types=["pyramidal"], dst_types=["pv_basket"]),
        rule("PV->L2L3", ["L2", "L3"], ["L2", "L3"], comp="soma", receptor="GABA_A",
             radius=0.5, space="cortical_3d", k=6, prob=0.6, w_med=2.2,
             src_types=["pv_basket"], dst_types=["pyramidal"]),
        rule("L2L3->SST", ["L2", "L3"], ["L2", "L3"], comp="soma", radius=0.5,
             space="cortical_3d", k=4, prob=0.4, w_med=1.6,
             src_types=["pyramidal"], dst_types=["sst_martinotti"]),
        rule("SST->apical", ["L2", "L3"], ["L2", "L3"], comp="apical",
             receptor="GABA_A", radius=0.7, space="cortical_3d", k=5, prob=0.5,
             w_med=1.8, src_types=["sst_martinotti"], dst_types=["pyramidal"],
             note="SST 는 첨단수상돌기 표적 억제"),
        rule("L2L3->L5", ["L2", "L3"], ["L5"], radius=0.6, space="surface", k=5,
             prob=0.5, w_med=2.4, src_types=["pyramidal"], dst_types=["pyramidal"],
             delay=0.9),
        rule("L5->L6", ["L5"], ["L6"], radius=0.6, space="surface", k=4, prob=0.5,
             w_med=2.2, src_types=["pyramidal"], dst_types=["pyramidal"], delay=0.9),
        rule("L6->L4", ["L6"], ["L4"], radius=0.6, space="surface", k=4, prob=0.4,
             w_med=1.2, src_types=["pyramidal"], dst_types=["spiny_stellate"],
             delay=1.1, note="층내 피드백"),
        rule("L5->L1_inh", ["L5"], ["L1"], comp="soma", radius=0.9, space="surface",
             k=3, prob=0.5, w_med=1.8, src_types=["pyramidal"],
             dst_types=["l1_inhibitory"], delay=1.0),
        rule("L1_inh->apical", ["L1"], ["L2", "L3", "L5"], comp="apical",
             receptor="GABA_A", radius=0.9, space="surface", k=6, prob=0.5,
             w_med=1.6, src_types=["l1_inhibitory"], dst_types=["pyramidal"],
             vel=0.15, note="L1 맥락 경로. 정답을 아는 교사층이 아니다"),
    ]


def _interareal_rules(src: str, dst: str, *, sigma_deg: float, delay: float,
                      w_med: float, feedback: bool = False) -> list[dict[str, Any]]:
    """영역 간 배선. 상향은 L2/3 -> L4, 하향은 L4 밖(apical/L1, L5) 을 표적으로 한다."""
    if not feedback:
        return [{
            "name": f"{src}->{dst}_FF", "enabled": True,
            "src": {"area": src, "layers": ["L2", "L3"], "cell_types": ["pyramidal"]},
            "dst": {"area": dst, "layers": ["L4"], "cell_types": ["spiny_stellate"]},
            "target_compartment": "basal", "receptor": "AMPA",
            "selection": "rf_knn", "k": 8, "rf_match_sigma_deg": float(sigma_deg),
            "probability": 0.6, "w0_median_nS": float(w_med), "w0_sigma": 0.3,
            "w0_max_nS": 8.0, "conduction_velocity_mm_per_ms": 0.5,
            "synaptic_delay_ms": float(delay), "gabor_initialized": False,
            "note": "상향: 상부층 기원·중간층 표적이라는 집단 수준 경향 (혼합 허용)",
        }]
    return [{
        "name": f"{dst}->{src}_FB_apical", "enabled": True,
        "src": {"area": dst, "layers": ["L5", "L6"], "cell_types": ["pyramidal"]},
        "dst": {"area": src, "layers": ["L2", "L3"], "cell_types": ["pyramidal"]},
        "target_compartment": "apical", "receptor": "AMPA",
        "selection": "rf_knn", "k": 6, "rf_match_sigma_deg": float(sigma_deg),
        "probability": 0.45, "w0_median_nS": float(w_med), "w0_sigma": 0.3,
        "w0_max_nS": 8.0, "conduction_velocity_mm_per_ms": 0.5,
        "synaptic_delay_ms": float(delay), "gabor_initialized": False,
        "note": "하향: L4 밖(apical) 표적. 고정 배선이며 오차를 전달하지 않는다",
    }, {
        "name": f"{dst}->{src}_FB_L1", "enabled": True,
        "src": {"area": dst, "layers": ["L5", "L6"], "cell_types": ["pyramidal"]},
        "dst": {"area": src, "layers": ["L1"], "cell_types": ["l1_inhibitory"]},
        "target_compartment": "soma", "receptor": "AMPA",
        "selection": "rf_knn", "k": 4, "rf_match_sigma_deg": float(sigma_deg * 1.3),
        "probability": 0.4, "w0_median_nS": float(w_med * 0.8), "w0_sigma": 0.3,
        "w0_max_nS": 8.0, "conduction_velocity_mm_per_ms": 0.5,
        "synaptic_delay_ms": float(delay + 0.4), "gabor_initialized": False,
        "note": "하향: L1 맥락 경로",
    }]


PRESETS: tuple[str, ...] = ("tiny", "v1_small", "hierarchy_small", "megapixel_input")


def build_config(preset: str = "v1_small", *, include_v3: bool = False,
                 wiring_mode: str | None = None, fanin: dict[str, Any] | None = None,
                 budget_mode: str | None = None,
                 **overrides: Any) -> dict[str, Any]:
    """preset 이름 -> 해석된 설정 dict.

    모든 값이 여기에 모여 있고 그대로 ``resolved_config.json`` 에 저장된다.
    실행 기록만 보고도 무엇이 쓰였는지 알 수 있다.

    기본 감각 경로는 ``Image -> Retina -> LGN -> V1 -> V2 -> V4 -> IT`` 이고,
    ``include_v3=True`` 면 확장 경로 ``... V2 -> V3 -> V4 ...`` 를 쓴다.
    """
    preset = str(preset)
    if preset not in PRESETS:
        raise ValueError(f"알 수 없는 preset: {preset!r} (가능: {list(PRESETS)})")

    if preset == "tiny":
        image_px, n_radial, n_angular = 32, 2, 8
        v1_scale, higher, sample_ms = 4, [], 60.0
        it_counts = {"L1": 2, "L2": 6, "L3": 6, "L4": 6, "L5": 4, "L6": 4}
    elif preset == "v1_small":
        image_px, n_radial, n_angular = 64, 4, 12
        v1_scale, higher, sample_ms = 10, [], 120.0
        it_counts = {"L1": 4, "L2": 16, "L3": 16, "L4": 16, "L5": 10, "L6": 10}
    elif preset == "hierarchy_small":
        image_px, n_radial, n_angular = 64, 4, 12
        higher = ["V2", "V3", "V4"] if include_v3 else ["V2", "V4"]
        v1_scale, sample_ms = 10, 160.0
        it_counts = {"L1": 4, "L2": 20, "L3": 20, "L4": 16, "L5": 12, "L6": 12}
    else:                                   # megapixel_input
        image_px, n_radial, n_angular = 1024, 12, 32
        v1_scale, higher, sample_ms = 14, [], 120.0
        it_counts = {"L1": 4, "L2": 20, "L3": 20, "L4": 16, "L5": 12, "L6": 12}

    areas: dict[str, dict[str, Any]] = {
        "Retina": {"kind": "retina", "level": 0, "surface_extent_mm": [2.0, 2.0],
                   "cell_type": "retinal_ganglion", "rf_sigma_deg": 0.25},
        "LGN": {"kind": "thalamus", "level": 1, "surface_extent_mm": [1.5, 1.5],
                "cell_type": "lgn_relay", "rf_sigma_deg": 0.35,
                "relay_per_channel": max(2, (n_radial * n_angular) // 3)},
        "V1": _cortical_area(2, [1.6, 1.6], _v1_counts(v1_scale), 0.45),
    }
    rf = 0.9
    for i, name in enumerate(higher):
        areas[name] = _cortical_area(3 + i, [1.4, 1.4], _v1_counts(max(4, v1_scale - 2)), rf)
        rf *= 1.6
    areas["IT"] = _cortical_area(3 + len(higher), [1.2, 1.2], it_counts, rf * 1.6)

    # --- 연결 그래프: 직렬만 가정하지 않고 우회 경로를 명시한다 ---------
    cortical = ["V1"] + list(higher) + ["IT"]
    graph_ff: list[tuple[str, str]] = [(cortical[i], cortical[i + 1])
                                       for i in range(len(cortical) - 1)]
    if "V3" in higher and "V4" in higher:
        graph_ff.append(("V2", "V4"))       # V3 를 반드시 거치지 않는 우회
    if "V4" in higher:
        graph_ff.append(("V1", "V4"))       # V1 -> V4 bypass (병렬 경로)
    rules: list[dict[str, Any]] = []

    # 망막 -> LGN: 채널과 극성을 보존한다 (F04)
    rules.append({
        "name": "Retina->LGN", "enabled": True,
        "src": {"area": "Retina", "layers": [], "cell_types": []},
        "dst": {"area": "LGN", "layers": [], "cell_types": []},
        "target_compartment": "soma", "receptor": "AMPA",
        "selection": "channel_knn", "k": 4, "rf_match_sigma_deg": 0.6,
        "probability": 1.0, "w0_median_nS": 9.0, "w0_sigma": 0.25, "w0_max_nS": 24.0,
        "conduction_velocity_mm_per_ms": 1.0, "synaptic_delay_ms": 1.0,
        "gabor_initialized": False,
        "require_same_channel": True, "min_distinct_sources": 2,
        "note": "같은 (채널, 극성) 끼리만 잇는다. 채널 중복이 공간 수렴 수를 대신하지 않는다",
    })
    # LGN -> V1 L4: 부호 있는 Gabor 를 ON/OFF 와 흥분/억제로 나눈다 (F05)
    rules.append({
        "name": "LGN->V1_L4", "enabled": True,
        "src": {"area": "LGN", "layers": [], "cell_types": []},
        "dst": {"area": "V1", "layers": ["L4"], "cell_types": ["spiny_stellate"]},
        "target_compartment": "basal", "receptor": "AMPA",
        "selection": "rf_knn", "k": 12, "rf_match_sigma_deg": 0.7,
        "probability": 0.75, "w0_median_nS": 7.0, "w0_sigma": 0.3, "w0_max_nS": 24.0,
        "conduction_velocity_mm_per_ms": 0.5, "synaptic_delay_ms": 1.2,
        "gabor_initialized": True,
        "note": "초기 배선을 Gabor 모양으로 정했다. 이 선택성은 학습된 것이 아니다",
    })
    rules.append({
        "name": "LGN->V1_L4_PV", "enabled": True,
        "src": {"area": "LGN", "layers": [], "cell_types": []},
        "dst": {"area": "V1", "layers": ["L4"], "cell_types": ["pv_basket"]},
        "target_compartment": "soma", "receptor": "AMPA",
        "selection": "rf_knn", "k": 8, "rf_match_sigma_deg": 0.8,
        "probability": 0.5, "w0_median_nS": 6.0, "w0_sigma": 0.3, "w0_max_nS": 24.0,
        "conduction_velocity_mm_per_ms": 0.5, "synaptic_delay_ms": 1.1,
        "gabor_initialized": False, "note": "전방 억제",
    })
    for name in cortical:
        rules += _local_rules(name)
    for src, dst in graph_ff:
        lvl = abs(areas[dst]["level"] - areas[src]["level"])
        rules += _interareal_rules(src, dst, sigma_deg=0.9 * lvl + 0.3,
                                   delay=2.0 + 0.4 * lvl, w_med=3.0)
        rules += _interareal_rules(src, dst, sigma_deg=1.2 * lvl + 0.4,
                                   delay=3.0 + 0.4 * lvl, w_med=1.6, feedback=True)

    cfg: dict[str, Any] = {
        "meta": {
            "preset": preset, "version": __version__,
            "description": f"{preset} preset. 임계값 초기값 {THETA0}; 기본 학습 대상은 L2/L3 theta_base.",
            "claims": [
                "모든 수치는 모형 파라미터다. 생물학적 측정값이 아니다.",
                "이 결과를 인간 뇌의 완전한 복제라고 부르지 않는다.",
                "SPSA 는 전역 과제 오차를 쓰는 공학적 기준이다.",
            ],
        },
        "seed": 20260101,
        "device": "auto", "dtype": "float32", "reference_dtype": "float64",
        # 기본은 fast 모드다. True 로 두면 도착 합산이 표적 정렬 + 누적합 경로로 바뀌고
        # torch.use_deterministic_algorithms(True) 가 켜진다 (메모리·시간이 더 든다).
        "deterministic": False,
        "threshold": {"value": THRESHOLD, "v_unit_mV": V_UNIT_MV,
                      "trainable": True,
                      "note": f"초기값은 휴지막전위 대비 {THETA0} mV. 실제 학습 마스크와 조건은 threshold_learning 참조"},
        "engine": {
            "dt_ms": 1.0, "sample_ms": float(sample_ms), "min_delay_steps": 1,
            "delay_rounding": "ceil", "reset_between_samples": True,
            "nan_policy": "stop",
            "timing_note": "t_n 도착 반영 -> [t_n,t_n+1] 적분 -> 발화는 t_n+1 에 배정",
        },
        "image": {"max_side_px": int(image_px), "fov_deg": 12.0,
                  "input_colorspace": "srgb", "white_point": "D65"},
        "retina": {
            "dog": {"center_sigma_px": 1.0, "surround_sigma_px": 3.0,
                    "truncate": 4.0, "boundary": "reflect",
                    "normalize_kernel_sum": True},
            "lowpass_sigma_px": 6.0,
            "normalization": {"percentile": 99.0, "min_scale_ratio": 1e-3,
                              "fit_split": "train"},
            "drive": {"mode": "current", "input_gain": 1.0,
                      "current_per_unit_pA": 260.0, "baseline_pA": 0.0,
                      "poisson_rate_hz": 60.0, "poisson_pulse_nS": 6.0,
                      "note": "입력 코드값·주입 전류·실제 발화율은 서로 다른 값이다"},
        },
        "retinotopy": {"mapping": "log_polar", "e0_deg": 0.5,
                       "n_radial": int(n_radial), "n_angular": int(n_angular),
                       "fovea_patch": 2, "interpolation": "bilinear",
                       "prefilter_by_eccentricity": True},
        "areas": areas,
        "wiring": {"rules": rules, "max_total_synapses": 4_000_000,
                   "calibration_reference_threshold_mV": WEIGHT_CALIBRATION_THRESHOLD,
                   "graph_feedforward": [list(e) for e in graph_ff]},
        "v1": {
            "n_orientations": 12, "orientation_step_deg": 15.0,
            "phases_rad": [0.0, -math.pi / 2],
            "pinwheel": {"n_waves": 12, "hypercolumn_mm": 0.8},
            "gabor": {"sigma_deg": 0.35, "aspect": 1.6, "cycles_per_deg": 1.5},
            "note": "방향 12구간·위상 2개는 계산용 이산화다",
        },
        "decoder": {
            "area": "IT", "layers": ["L2", "L3"], "cell_types": ["pyramidal"],
            "classes": list(DEFAULT_CLASSES),
            "readout_start_ms": 0.4 * sample_ms, "readout_end_ms": float(sample_ms),
            "readout_scale": 1.0, "rate_unit_hz": 10.0, "bias": 0.0,
            "trainable": False,
            "note": "고정 해독기. 클래스 그룹은 인공적인 해독 규칙이다",
        },
        # ---- 이번 기본 조건: 초기 임계값 THETA0 에서 L2/L3 흥분성 임계값 학습 ----
        "threshold_learning": {
            "enabled": True,
            "condition": "proposed_local_threshold",
            "target_layers": ["L2", "L3"],
            "target_cell_types": ["pyramidal"],
            "target_dale": "excitatory",
            "theta0_mV": THETA0, "theta_min_mV": THETA_MIN,
            "theta_max_mV": THETA_MAX, "fast_bound_mV": FAST_BOUND,
            # 명세 13절의 첫 실행 가능 설정. 최적값이 아니라 부호·경로 점검용 출발값.
            "K_rounds": 3, "beta": 0.2, "deadband": 0.02, "error_scale": 0.1,
            "kappa_mV_per_round": 0.5, "eta_commit": 0.1, "rho_fast": 0.0,
            "confidence": 1.0, "early_stop": False,
            "attention": {"alpha_att": 0.0, "g_min": 0.5, "g_max": 1.5,
                          "apply_to_sensory": True, "apply_to_correction_gate": False},
            "homeostasis": False,
            "inhibitory_threshold_learning": False,
            "note_ko": ("과잉(r>0)이면 임계값을 올리고 부족(r<0)이면 내린다. "
                        "r = a - t 로 부호를 전체 프로그램에서 통일한다."),
        },
        # ---- 억제 점진 복원 실험 (선택 작업에서만 쓴다) ----------------
        # 기존 실행 모드는 gain=1.0 이라 동작이 그대로 보존된다.
        "inhibition": {
            "gain": INHIBITION_GAIN_DEFAULT,   # 현재 배율. 기존 모드는 항상 1.0
            "start": 0.01, "end": 1.0,
            "warmup_epochs": 5, "ramp_epochs": 20, "hold_epochs": 5,
            "schedule": "cosine",
            "scan_values": list(INHIBITION_SCAN_VALUES),
            "condition": "ramp_local",
            "eval_gain": None,                 # None 이면 스케줄의 end 로 평가
            # 작업 A 의 판정 기준. **사전에 공개**하고 결과에 맞춰 바꾸지 않는다.
            "criteria": {
                "transmits_min_active_fraction": 0.02,
                "it_distinguishable_min_pair_distance": 1e-6,
                "it_distinguishable_min_variance": 1e-12,
                "blank_response_max_active_fraction": 0.50,
                "saturation_max_fraction": 0.80,
                "note_ko": ("chain_transmits 하나로 축약하지 않는다. 전달성, IT 입력 "
                            "구별 가능성, 무입력 반응, 포화를 각각 보고한다."),
            },
            "note_ko": ("억제성 뉴런의 **출력 효과** 배율이다. alpha_att (주의) 와 "
                        "다른 변수다. 세포를 삭제하거나 발화를 0 으로 만들지 않고, "
                        "w0 와 역전위도 바꾸지 않는다. 배율을 바꿔도 초기 전도도 "
                        "보정을 다시 하지 않는다."),
        },
        # ---- 배선/강도 균형 대조 실험 (선택 작업에서만 쓴다) -----------
        # 기본 실행에는 아무 영향이 없다. 개입은 시뮬레이션 시작 **전에**
        # 정해진 연결군에 한 번만 적용한다.
        "wiring_balance": {
            "conditions": list(WIRING_CONDITIONS),
            "seeds": list(WIRING_DEFAULT_SEEDS),
            # 진단 대상 연결군. 실제 존재 여부는 실행 시 규칙 목록에서 확인한다.
            "target_groups": [],           # 비우면 아래 preferred 순서로 자동 선택
            # 명세 4절이 요구한 진단 범위. 실제 존재 여부는 실행 시 규칙 목록에서
            # 확인하며, 없는 이름은 'not_present' 로 보고하고 넘어간다.
            "preferred_groups": [
                "V1_L4->L2L3", "V1->V2_FF", "V2_L4->L2L3", "V2->V4_FF",
                "V4_L4->L2L3", "V4->IT_FF", "IT_L4->L2L3",
            ],
            # 우회(bypass) 입력. 개별 연결군과 전체 입력을 혼동하지 않기 위해
            # 따로 식별한다.
            "bypass_groups": ["V1->V4_FF"],
            "inhibition_gain": 0.01,       # 기본 비교값. 0.0 은 보조 비교
            "aux_inhibition_gain": 0.0,
            "degree": {
                "min_in_degree": 2,        # 요청값. 예산·후보 때문에 달성 못할 수 있다
                "max_iterations": 20000,
                "preserve_out_degree": True,
                "preserve_total_synapses": True,
                "rf_sigma_multiplier": 1.0,   # 허용 후보의 시야 거리 배수
            },
            "strength": {
                "lo_multiplier": 0.5,      # 보정 **이후** 기준 가중치 대비 하한
                "hi_multiplier": 2.0,      # 보정 이후 기준 가중치 대비 상한
                "max_iterations": 200,
                "preserve_total_weight": True,
            },
            "sham": {"max_iterations": 20000, "match_changed_edges": True},
            "record": {
                "input_timeseries": False,   # 선택형. 상한을 두고 잘린 구간을 남긴다
                "max_timeseries_rows": 500_000,
                "max_event_rows": 500_000,
            },
            "fixed_source_train": True,    # baseline q_i(t) 고정 재집계 보조 분석
            "note_ko": ("배선 균형화는 **공학적 개입**이다. 실제 뇌가 같은 최적화를 "
                        "수행한다거나 모든 뉴런이 동일하게 반응해야 한다는 뜻이 "
                        "아니다. 분기 전달 시 출력량을 연결 개수로 나누는 새 규칙을 "
                        "도입하지 않는다."),
        },
        "readout_prep": {
            "classifier": {"kind": "linear_ce_last_module", "epochs": 30,
                           "lr": 0.05, "l2": 1e-4},
            "image_decoder": {"size_px": 32, "kind": "linear_lms", "epochs": 30,
                              "lr": 0.05, "l2": 1e-4},
            "local_decoder": {"kind": "learned_linear", "eta_D": 0.05, "epochs": 20,
                              "rf_overlap_only": True, "max_fanout": 64},
            "prototypes": {"per_class": 3, "source": "train_preparation"},
            "rate_scale_percentile": 95.0,
            "n_preparation_samples": 0,   # 0 이면 train 전체
            "note_ko": ("준비 단계는 선택한 학습 실행 안에서 수행한다. 감각 네트워크로 "
                        "기울기를 전달하지 않는다. 준비가 끝나면 C/D_img/D_l/프로토타입은 "
                        "주 비교 동안 고정한다."),
        },
        "training": {
            "mode": "proposed_local_threshold",
            "P_min": 0.0, "P_max": 4.0, "P_init": 1.0,
            "eta": 0.05, "c": 0.02, "K": 1,
            "eta_schedule": "constant", "c_schedule": "constant",
            "batch_size": 4, "epochs": 2, "max_samples_per_epoch": 0,
            "p_regularization": 0.0,
            "optimizer": "plain_sgd",
            "trainable_allowlist": ["theta_base"],
            "train_mask": "all",
            "note": ("이번 기본은 theta_base 만 학습한다. W/P/C/D_img/D_l/프로토타입은 "
                     "준비 후 고정한다. legacy_* 조건에서만 P(z) 를 학습한다."),
        },
        "data": {
            "mode": "paired_image",       # paired_image | label_only
            "n_base_per_class": 6, "n_variants": 2, "split_fractions": [0.6, 0.2, 0.2],
            "split_by": "base_id", "diagnostic_separate": True,
            "corruption": {"erase_fraction": 0.35, "add_fraction": 0.2,
                           "noise_sigma": 0.04, "occlusion_fraction": 0.0},
            "note_ko": ("paired_image 는 같은 장면의 clean_target 과 손상된 "
                        "observed_input 을 만든다. 감각 입력은 observed_input 뿐이고 "
                        "clean/마스크는 teacher·평가 전용이다."),
        },
        "recording": {
            "mode": "selected", "backend": "auto",
            "n_selected_per_area": 4,
            "event_budget_rows": 200_000, "state_budget_rows": 200_000,
            "state_every_steps": 4, "queue_max_items": 64,
            "note": "선택 기록은 예산을 표본에 배분한다. 한도 초과는 명시적으로 중단",
        },
        "limits": {"max_vram_mb": 0, "max_ram_mb": 0, "edge_chunk": 2_000_000},
        "benchmark": {"warmup_steps": 5, "measure_steps": 30},
    }
    cfg["transmission_calibration"] = transmission_calibration_defaults()
    # ---- 4.0 대응 배선·이중 교정·엔진 (legacy 가 기본: 규칙을 바꾸지 않는다) ----
    cfg["paired"] = paired_defaults()
    cfg["engine_model"] = engine_model_defaults()
    for key, val in overrides.items():
        if key not in cfg:
            raise KeyError(f"알 수 없는 설정 키: {key!r}")
        if isinstance(cfg[key], dict) and isinstance(val, dict):
            cfg[key].update(val)
        else:
            cfg[key] = val
    configure_paired(cfg, str(wiring_mode or cfg["paired"]["wiring_mode"]),
                     fanin=fanin, budget_mode=budget_mode)
    validate_config(cfg)
    return cfg


def validate_config(cfg: dict[str, Any]) -> None:
    """설정 자체의 모순을 **실행 전에** 잡는다."""
    def need(cond: bool, msg: str) -> None:
        if not cond:
            raise ValueError(f"설정 오류: {msg}")

    need(cfg["threshold"]["value"] == THETA0,
         f"임계값 **초기값**은 {THETA0} 이다 (설정으로 바꾸지 않는다)")
    need(cfg["decoder"]["trainable"] is False, "고정 해독기를 학습 대상으로 둘 수 없다")
    tl = cfg["threshold_learning"]
    need(tl["theta0_mV"] == THETA0, "threshold_learning.theta0_mV 와 초기 임계값이 일치해야 한다")
    need(cfg["wiring"].get("calibration_reference_threshold_mV",
                           WEIGHT_CALIBRATION_THRESHOLD) == WEIGHT_CALIBRATION_THRESHOLD,
         "초기 가중치 보정 기준은 15 mV로 유지한다 (발화 초기값 10 mV와 별도)")
    need(tl["condition"] in THRESHOLD_CONDITIONS,
         f"threshold_learning.condition 은 {list(THRESHOLD_CONDITIONS)} 중 하나다")
    need(tl["theta_min_mV"] < tl["theta0_mV"] < tl["theta_max_mV"],
         "theta_min < theta0 < theta_max 여야 한다")
    need(tl["fast_bound_mV"] > 0, "fast_bound 는 양수")
    need(int(tl["K_rounds"]) >= 1, "K_rounds 는 1 이상")
    need(tl["deadband"] >= 0.0, "deadband 는 0 이상")
    need(tl["error_scale"] > 0.0, "error_scale 은 양수")
    need(0.0 <= tl["rho_fast"] <= 1.0, "rho_fast 는 [0,1]")
    need(tl["eta_commit"] >= 0.0, "eta_commit 은 0 이상")
    need(tl["beta"] >= 0.0, "beta 는 0 이상")
    att = tl["attention"]
    need(0.0 < att["g_min"] <= 1.0 <= att["g_max"],
         "attention gain 범위는 g_min <= 1 <= g_max 여야 한다 (기본 1 이면 무효과)")
    need(tl["inhibitory_threshold_learning"] is False
         or tl["condition"] != "proposed_local_threshold",
         "억제성 임계값 학습은 기본 비교에서 끈다 (별도 연구 옵션)")
    need(cfg["data"]["mode"] in DATA_MODES,
         f"data.mode 는 {list(DATA_MODES)} 중 하나다")
    need(list(cfg["training"]["trainable_allowlist"]) in (["z"], ["theta_base"]),
         "학습 대상은 theta_base (이번 기본) 또는 legacy 의 z 뿐이다")
    eng = cfg["engine"]
    need(eng["dt_ms"] > 0, "engine.dt_ms 는 양수")
    need(eng["sample_ms"] > 0, "engine.sample_ms 는 양수")
    need(int(eng["min_delay_steps"]) >= 1, "min_delay_steps 는 1 이상 (0 지연 재귀 금지)")
    tr = cfg["training"]
    need(tr["P_min"] >= 0.0, "P_min 은 0 이상 (출력 이득은 비음수)")
    need(tr["P_max"] > tr["P_min"], "P_max > P_min")
    need(tr["P_min"] < tr["P_init"] < tr["P_max"] or tr["P_init"] == tr["P_min"],
         "P_init 은 [P_min, P_max) 안이어야 한다")
    need(int(tr["K"]) >= 1, "SPSA K 는 1 이상")
    need(tr["c"] > 0 and tr["eta"] > 0, "SPSA c, eta 는 양수")
    need(tr["optimizer"] == "plain_sgd",
         "기본 갱신은 단순 식이다. 다른 최적화기는 별도 옵션·기록이 필요하다")
    dec = cfg["decoder"]
    need(0.0 <= dec["readout_start_ms"] < dec["readout_end_ms"] <= eng["sample_ms"],
         "readout 시간창은 [start, end) 이고 sample_ms 안이어야 한다")
    need(len(dec["classes"]) >= 2, "클래스가 2개 이상이어야 한다")
    need(len(set(dec["classes"])) == len(dec["classes"]), "클래스 이름이 중복됐다")
    need(dec["area"] in cfg["areas"], f"decoder.area {dec['area']!r} 가 영역에 없다")
    rec = cfg["recording"]
    need(rec["mode"] in ("full", "selected", "summary"),
         "recording.mode 는 full|selected|summary")
    need(rec["backend"] in ("auto", "hdf5", "npz"), "recording.backend 는 auto|hdf5|npz")
    for r in cfg["wiring"]["rules"]:
        tag = f"wiring 규칙 {r['name']!r}"
        need(r["src"]["area"] in cfg["areas"], f"{tag}: 알 수 없는 src.area")
        need(r["dst"]["area"] in cfg["areas"], f"{tag}: 알 수 없는 dst.area")
        need(r["receptor"] in RECEPTORS, f"{tag}: 알 수 없는 receptor")
        need(r["target_compartment"] in COMPARTMENTS, f"{tag}: 알 수 없는 구획")
        need(r["selection"] in ("rf_knn", "local_radius", "channel_knn", "paired_map"),
             f"{tag}: 알 수 없는 selection {r['selection']!r}")
        need(r.get("radius_space", "cortical_3d") in ("cortical_3d", "surface"),
             f"{tag}: radius_space 는 cortical_3d|surface")
        need(r["w0_median_nS"] >= 0 and r["w0_max_nS"] > 0, f"{tag}: w0 는 비음수")
        need(r["conduction_velocity_mm_per_ms"] > 0, f"{tag}: 전도 속도는 양수")
        need(r["synaptic_delay_ms"] >= 0, f"{tag}: 시냅스 지연은 0 이상")
    # ---- 억제 점진 복원 설정 (명세 4절) ----------------------------
    inh = cfg["inhibition"]
    for key in ("gain", "start", "end"):
        v = float(inh[key])
        need(math.isfinite(v), f"inhibition.{key} 는 유한수여야 한다 (지금 {v!r})")
        need(INHIBITION_GAIN_MIN <= v <= INHIBITION_GAIN_MAX,
             f"inhibition.{key} 는 [0, 1] 범위다 (지금 {v})")
    need(float(inh["start"]) <= float(inh["end"]),
         f"0 <= start <= end <= 1 이어야 한다 "
         f"(start={inh['start']}, end={inh['end']})")
    need(int(inh["ramp_epochs"]) >= 1, "inhibition.ramp_epochs 는 1 이상")
    need(int(inh["warmup_epochs"]) >= 0, "inhibition.warmup_epochs 는 0 이상")
    need(int(inh["hold_epochs"]) >= 0, "inhibition.hold_epochs 는 0 이상")
    need(str(inh["schedule"]) in INHIBITION_SCHEDULES,
         f"inhibition.schedule 은 {list(INHIBITION_SCHEDULES)} 중 하나다")
    need(str(inh["condition"]) in (INHIBITION_CONDITIONS
                                  + INHIBITION_OPTIONAL_CONDITIONS),
         f"inhibition.condition 은 "
         f"{list(INHIBITION_CONDITIONS + INHIBITION_OPTIONAL_CONDITIONS)} 중 하나다")
    vals = list(inh["scan_values"])
    need(len(vals) >= 1, "inhibition.scan_values 가 비어 있다")
    for v in vals:
        need(math.isfinite(float(v))
             and INHIBITION_GAIN_MIN <= float(v) <= INHIBITION_GAIN_MAX,
             f"inhibition.scan_values 원소는 [0, 1] 의 유한수다 (지금 {v!r})")
    if inh.get("eval_gain") is not None:
        ev = float(inh["eval_gain"])
        need(math.isfinite(ev) and INHIBITION_GAIN_MIN <= ev <= INHIBITION_GAIN_MAX,
             f"inhibition.eval_gain 은 [0, 1] 의 유한수다 (지금 {ev})")
    crit = inh["criteria"]
    for key in ("transmits_min_active_fraction", "blank_response_max_active_fraction",
                "saturation_max_fraction"):
        v = float(crit[key])
        need(math.isfinite(v) and 0.0 <= v <= 1.0,
             f"inhibition.criteria.{key} 는 [0, 1] 의 유한수다 (지금 {v})")
    # 배율을 바꿔도 초기 전도도 보정 기준은 그대로다 (명세 2절 3항)
    need(cfg["wiring"].get("calibration_reference_threshold_mV",
                           WEIGHT_CALIBRATION_THRESHOLD)
         == WEIGHT_CALIBRATION_THRESHOLD,
         "억제 배율을 바꿔도 초기 전도도 보정 기준을 다시 잡지 않는다")

    validate_transmission_profile(cfg)
    tc = cfg.get("transmission_calibration", transmission_calibration_defaults())
    grid = tc["gain_grid"]
    need(bool(grid) and float(grid[0]) == 1.0, "전달 보정 배율은 1부터 시작한다")
    need(all(math.isfinite(float(v)) and 1 <= float(v) <= 16 for v in grid),
         "전달 보정 배율은 유한수 [1,16]이어야 한다")
    need(all(float(a) < float(b) for a, b in zip(grid, grid[1:])),
         "전달 보정 배율은 중복 없이 증가해야 한다")
    need(int(tc["batch_size"]) >= 1 and int(tc["fit_max_samples"]) >= 0,
         "전달 보정 배치 크기는 양수, 표본 수는 0 이상")
    for key in ("min_mean_active_fraction", "min_sample_response_fraction",
                "max_population_saturation_fraction"):
        need(math.isfinite(float(tc[key])) and 0 < float(tc[key]) <= 1,
             f"transmission_calibration.{key}는 (0,1] 범위")
    for key in ("max_mean_rate_hz", "max_edge_conductance_nS"):
        need(math.isfinite(float(tc[key])) and float(tc[key]) > 0,
             f"transmission_calibration.{key}는 유한 양수")
    # ---- 배선/강도 균형 대조 실험 설정 -----------------------------
    wb = cfg["wiring_balance"]
    for c in wb["conditions"]:
        need(c in WIRING_CONDITIONS,
             f"wiring_balance.conditions 원소는 {list(WIRING_CONDITIONS)} 중 하나다 "
             f"(지금 {c!r})")
    need("C0_baseline" in wb["conditions"],
         "C0_baseline 은 항상 포함해야 한다 (짝지은 비교의 기준이다)")
    need(len(set(wb["seeds"])) == len(wb["seeds"]),
         f"wiring_balance.seeds 에 중복이 있다: {wb['seeds']}")
    need(len(wb["seeds"]) >= 1, "wiring_balance.seeds 가 비어 있다")
    for g in ("inhibition_gain", "aux_inhibition_gain"):
        v = float(wb[g])
        need(math.isfinite(v) and INHIBITION_GAIN_MIN <= v <= INHIBITION_GAIN_MAX,
             f"wiring_balance.{g} 는 [0, 1] 의 유한수다 (지금 {v})")
    need(float(wb["inhibition_gain"]) != float(wb["aux_inhibition_gain"]),
         "기본 억제 gain 과 보조 gain 이 같으면 두 비교를 구분할 수 없다")
    deg = wb["degree"]
    need(int(deg["min_in_degree"]) >= 0, "degree.min_in_degree 는 0 이상")
    need(int(deg["max_iterations"]) >= 1, "degree.max_iterations 는 1 이상")
    need(float(deg["rf_sigma_multiplier"]) > 0, "degree.rf_sigma_multiplier 는 양수")
    st = cfg["wiring_balance"]["strength"]
    need(0.0 < float(st["lo_multiplier"]) <= 1.0,
         f"strength.lo_multiplier 는 (0, 1] (지금 {st['lo_multiplier']})")
    need(float(st["hi_multiplier"]) >= 1.0,
         f"strength.hi_multiplier 는 1 이상 (지금 {st['hi_multiplier']})")
    need(int(st["max_iterations"]) >= 1, "strength.max_iterations 는 1 이상")
    rc = wb["record"]
    need(int(rc["max_timeseries_rows"]) >= 1, "record.max_timeseries_rows 는 1 이상")
    need(int(rc["max_event_rows"]) >= 1, "record.max_event_rows 는 1 이상")

    # ---- 4.0 대응 배선·이중 교정·엔진 -------------------------------
    pc = cfg.get("paired")
    if pc is not None:
        need(pc["wiring_mode"] in PAIRED_WIRING_MODES,
             f"paired.wiring_mode 는 {list(PAIRED_WIRING_MODES)} 중 하나다")
        fan = pc["fanin"]
        need(1 <= int(fan["K_min"]) <= int(fan["K_max"]), "1 <= K_min <= K_max")
        need(float(fan["r0_deg"]) > 0 and float(fan["c"]) >= 0,
             "fanin.r0_deg 는 양수, c 는 0 이상")
        need(float(fan["candidate_radius_rf_multiplier"]) > 0,
             "fanin.candidate_radius_rf_multiplier 는 양수")
        need(str(fan.get("candidate_radius_mode", "fixed"))
             in ("fixed", "scaled_by_eccentricity"),
             "fanin.candidate_radius_mode 는 fixed|scaled_by_eccentricity")
        need(fan["budget_mode"] in PAIRED_BUDGET_MODES,
             f"fanin.budget_mode 는 {list(PAIRED_BUDGET_MODES)} 중 하나다")
        fb = pc["feedback"]
        need(fb["condition"] in PAIRED_CONDITIONS,
             f"paired.feedback.condition 은 {list(PAIRED_CONDITIONS)} 중 하나다")
        need(fb["teacher_gate_rule"] in PAIRED_GATE_RULES,
             f"teacher_gate_rule 은 {list(PAIRED_GATE_RULES)} 중 하나다")
        need(fb["l3_to_l2_projection"] in PAIRED_PROJECTIONS,
             f"l3_to_l2_projection 은 {list(PAIRED_PROJECTIONS)} 중 하나다")
        need(fb["confidence_mode"] in ("restorer_reliability", "constant"),
             "confidence_mode 는 restorer_reliability|constant")
        need(int(fb["max_iterations"]) >= 1, "max_iterations 는 1 이상")
        need(float(fb["beta"]) >= 0 and all(float(v) >= 0
                                            for v in fb["beta_by_area"].values()),
             "beta 는 0 이상")
        need(float(fb["deadband"]) >= 0 and float(fb["error_scale"]) > 0,
             "deadband >= 0, error_scale > 0")
        lo_c, hi_c = (float(v) for v in fb["target_clip"])
        need(lo_c < hi_c, "target_clip 은 lo < hi")
        dcp = fb["decomposition"]
        need(0.0 <= float(dcp["shape_dominant_fraction"])
             < float(dcp["intensity_dominant_fraction"]) <= 1.0,
             "0 <= shape_dominant_fraction < intensity_dominant_fraction <= 1")
        need(float(dcp["eps_norm"]) > 0 and float(dcp["tile_mm"]) > 0,
             "eps_norm, tile_mm 는 양수")
        if pc["wiring_mode"] != "legacy":
            need(any(r.get("selection") == "paired_map" and r.get("enabled", True)
                     for r in cfg["wiring"]["rules"]),
                 "대응 배선 모드인데 대응 규칙이 없다 (configure_paired 를 거치지 않았다)")
    em = cfg.get("engine_model")
    if em is not None:
        need(em["kind"] in ENGINE_KINDS, f"engine_model.kind 는 {list(ENGINE_KINDS)} 중 하나다")

    rt = cfg["retinotopy"]
    need(rt["e0_deg"] > 0, "retinotopy.e0_deg 는 양수")

    need(rt["n_radial"] >= 1 and rt["n_angular"] >= 1, "격자 크기는 1 이상")
    need(cfg["image"]["max_side_px"] >= 8, "image.max_side_px 는 8 이상")
    need(cfg["image"]["fov_deg"] > 0, "image.fov_deg 는 양수")


def config_hash(cfg: dict[str, Any]) -> str:
    return sha256_text(json.dumps(cfg, ensure_ascii=False, sort_keys=True,
                                  separators=(",", ":"), default=_json_default))


