def _fmt_opt(v: Any, digits: int = 4) -> str:
    """None 은 'n/a' 로 찍는다. 정의 불가를 0 으로 보이게 하지 않는다."""
    if v is None:
        return "n/a"
    if isinstance(v, float):
        return f"{v:.{digits}f}"
    return str(v)


def _ask(prompt: str, default: str = "") -> str:
    suffix = f" [{default}]" if default else ""
    try:
        val = input(f"{prompt}{suffix}: ").strip()
    except EOFError:
        return default
    return val or default


def _ask_preset() -> str:
    while True:
        p = _ask(f"preset ({'/'.join(PRESETS)})", "v1_small")
        if p in PRESETS:
            return p
        print(f"  '{p}' 은(는) 없는 preset 이다.")


def _ask_device(env: EnvironmentInfo) -> str:
    default = "auto"
    while True:
        d = _ask("장치 (auto/cuda/cpu)", default)
        if d in ("auto", "cuda", "cpu"):
            if d == "cuda" and not env.cuda_available:
                print("  CUDA 를 쓸 수 없다. auto 또는 cpu 를 고르거나 CUDA 빌드 "
                      "torch 를 설치하라: https://pytorch.org/get-started/locally/")
                continue
            return d
        print("  auto, cuda, cpu 중에서 고르라.")


def _ask_output_dir() -> Path:
    while True:
        raw = _ask("기록을 저장할 폴더 경로를 붙여넣으세요 (공백·한글·따옴표 가능)")
        if not raw:
            print("  폴더 경로가 필요하다.")
            continue
        try:
            path = clean_user_path(raw)
            return ensure_writable_dir(path)
        except (OSError, ValueError) as exc:
            print(f"  [경로 오류] {exc}")


class KoreanMenu:
    """사용자가 고른 작업만 실행하는 한국어 메뉴."""

    def __init__(self) -> None:
        self.env = EnvironmentInfo.detect()
        self.output: Path | None = None
        self.preset = "v1_small"
        self.device_choice = "auto"
        self.calibrated_cfg: dict[str, Any] | None = None
        #: 4.0: 메뉴 14-A 에서 고른 배선·엔진. 기본은 3.2.2 와 같은 legacy.
        self.wiring_mode = "legacy"
        self.engine_kind = ENGINE_KINDS[0]
        self.budget_mode = "summed"

    def show_setup(self) -> None:
        cfg = build_config(self.preset)
        print()
        print(f"[설정] preset={self.preset}, seed={cfg['seed']}, "
              f"dtype={cfg['dtype']}, device 요청={self.device_choice}")
        tl = cfg["threshold_learning"]
        print(f"  임계값 초기값 {tl['theta0_mV']} (모든 뉴런 동일), "
              f"V_unit={V_UNIT_MV} mV")
        print(f"  초기 연결 강도 보정 기준: {WEIGHT_CALIBRATION_THRESHOLD} mV (발화 기준과 별도)")
        print(f"  임계값 학습: {tl['enabled']} / 조건 {tl['condition']} / "
              f"대상 {tl['target_layers']} {tl['target_cell_types']} "
              f"(경계 {tl['theta_min_mV']}~{tl['theta_max_mV']} mV)")
        print(f"  데이터 모드: {cfg['data']['mode']} / 클래스 "
              f"{len(cfg['decoder']['classes'])}개")
        print(f"  한 표본 {cfg['engine']['sample_ms']} ms / dt {cfg['engine']['dt_ms']} ms "
              f"= {int(cfg['engine']['sample_ms'] / cfg['engine']['dt_ms'])} 스텝")
        print(f"  기록 모드: {cfg['recording']['mode']} "
              f"(backend={cfg['recording']['backend']})")
        mode = cfg["training"]["mode"]
        target = ("L2/L3 흥분성 뉴런의 theta_base" if is_threshold_condition(mode)
                  else "출력 이득 P 뿐 (legacy)")
        print(f"  학습 대상: {target} (조건 {mode})")
        print("  규모·메모리 예상은 메뉴 1번에서 실제로 모델을 만들어 계산한다.")
        print("  readout/decoder 준비는 메뉴 5 학습 작업 안의 준비 단계다.")
        print(f"  배선 모드: {self.wiring_mode} / 엔진: {self.engine_kind} "
              f"(메뉴 14-A 에서 바꾼다. 기본 legacy = 3.2.2 배선)")

    def loop(self) -> int:
        print(self.env.describe_ko())
        if torch is None:
            print("\nPyTorch 가 없어 계산을 실행할 수 없다. 위 안내를 보고 설치하라.")
            return 2
        self.output = _ask_output_dir()
        self.preset = _ask_preset()
        self.device_choice = _ask_device(self.env)
        self.show_setup()
        while True:
            print(MENU_TEXT)
            choice = _ask("번호를 선택하라", "0")
            try:
                if choice == "0":
                    print("종료한다. (다른 작업을 자동으로 실행하지 않는다.)")
                    return 0
                self.dispatch(choice)
            except KeyboardInterrupt:
                print("\n[중단] 작업을 중단했다. 마지막 완료 지점의 기록은 남아 있다.")
            except Exception as exc:
                print(f"\n[오류] {type(exc).__name__}: {exc}")
                traceback.print_exc(limit=3)

    @staticmethod
    def _show_recent_runs(out: Path, limit: int = 8) -> None:
        """결과 루트 아래의 최근 실행 폴더를 보여 준다 (비교 실행의 하위 폴더 포함)."""
        found: list[Path] = []
        try:
            for d in sorted(out.iterdir()):
                if not d.is_dir():
                    continue
                if (d / "manifest.json").is_file():
                    found.append(d)
                    continue
                for sub in sorted(d.iterdir()):
                    if sub.is_dir() and (sub / "manifest.json").is_file():
                        found.append(sub)
        except OSError as exc:
            print(f"  [알림] 결과 폴더를 읽지 못했다: {exc}")
            return
        if not found:
            print(f"  [알림] {out} 아래에 아직 실행 폴더가 없다.")
            return
        found.sort(key=lambda d: d.stat().st_mtime, reverse=True)
        print("  최근 실행 폴더:")
        for d in found[:limit]:
            print(f"    - {d}")

    def dispatch(self, choice: str) -> None:
        cfg = self._base_cfg()
        out = self.output
        assert out is not None
        if choice != "14":
            self._model_notice(cfg)
        if choice == "1":
            runner = ExperimentRunner(cfg, output_root=out,
                                      device_choice=self.device_choice, env=self.env)
            info = runner.run_inspect()
            print(dumps(info)[:4000])
            print("\n[알림] 위 값은 실행 전 추정이다. 실제 속도는 메뉴 10 에서 측정한다.")
        elif choice == "2":
            res = run_validation(cfg, out, self.device_choice,
                                 progress=lambda m: print(f"  … {m}"))
            print(f"\n검사 {res['n_checks']}건: 통과 {res['n_passed']} / "
                  f"실패 {res['n_failed']} / 건너뜀 {res['n_skipped']} / "
                  f"해당없음 {res['n_not_applicable']} / 미실행 {res['n_not_run']} / "
                  f"측정만 {res['n_measured']} / 미지원 {res['n_not_supported']}")
            for c in res["checks"]:
                print(f"  [{c['status']:>15s}] {c['name']}")
            print(f"\n결과: {res['run_dir']}")
        elif choice == "3":
            runner = ExperimentRunner(cfg, output_root=out,
                                      device_choice=self.device_choice, env=self.env)
            res = runner.run_diagnose()
            print(dumps(res["verdict"]))
            for area, v in res["positive_control"]["by_area"].items():
                print(f"  {area:8s} 스파이크 {v['total_spikes']:8d} "
                      f"평균 {v['mean_rate_hz']:7.2f} Hz  "
                      f"임계 여유 u {v['threshold_margin_u_max']:+.3f}")
            print(f"\n결과: {runner.run_dir}")
        elif choice == "4":
            path = _ask("영상 파일 경로 PNG/JPG (폴더가 아님, 비우면 내장 도형 사용)", "")
            ckpt = _ask("학습이 완료된 train_... 폴더 (영상 폴더가 아님, 비우면 추론 생략)", "")
            runner = ExperimentRunner(cfg, output_root=out,
                                      device_choice=self.device_choice, env=self.env)
            ck = clean_user_path(ckpt) if ckpt else None
            if path:
                res = runner.run_simulate(image_path=clean_user_path(path),
                                          checkpoint=ck)
            else:
                sid = _ask("자극 ID (비우면 train 첫 자극)", "")
                res = runner.run_simulate(stimulus_id=sid or None, checkpoint=ck)
            print(dumps({k: v for k, v in res.items() if k != "by_area"}))
            for area, v in res["by_area"].items():
                print(f"  {area:8s} 스파이크 {v['spikes']:8d} "
                      f"평균 {v['mean_rate_hz']:7.2f} Hz")
            print(f"\n결과: {runner.run_dir}")
        elif choice == "5":
            print("\n  임계값 학습 조건 (이번 기본):")
            for name in THRESHOLD_CONDITIONS:
                print(f"    - {name}")
            print("  legacy P-only 조건:")
            for name in LEGACY_GAIN_MODES:
                print(f"    - {name}")
            print("  이 작업 안에서 rate_scale / 분류기 C / D_img / D_l / 프로토타입 "
                  "준비 단계를 먼저 실행한다.")
            folder = _ask("클래스별 폴더 데이터 루트 (비우면 합성 도형 사용)", "")
            if folder:
                print("  외부 폴더 데이터에는 clean 정답이 없으므로 "
                      "data.mode 를 label_only 로 바꾼다.")
                cfg["data"]["mode"] = "label_only"
            mode = _ask("학습 조건", "proposed_local_threshold")
            if mode not in TRAIN_MODES:
                print(f"  '{mode}' 는 없는 조건이다. 위 목록에서 고르라.")
                return
            n_cortex = sum(1 for v in cfg["areas"].values() if v["kind"] == "cortex")
            if is_threshold_condition(mode) and n_cortex < 4:
                print(f"  [알림] preset '{self.preset}' 의 피질 영역은 {n_cortex}개다. "
                      f"명세의 기본 경로(V1->V2->V4->IT)보다 얕아 영역 간 목표 전달 "
                      f"단계가 적다.")
                print("         더 깊은 비교를 원하면 프로그램을 다시 시작해 "
                      "hierarchy_small preset 을 고르라. 여기서 규모를 조용히 "
                      "바꾸지 않는다.")
            epochs = int(_ask("에폭 수", str(cfg["training"]["epochs"])))
            prep = _ask("재사용할 준비 체크포인트 경로 (비우면 새로 준비)", "")
            runner = ExperimentRunner(cfg, output_root=out,
                                      device_choice=self.device_choice, env=self.env)
            runner.image_folder = clean_user_path(folder) if folder else None
            res = runner.run_train(
                mode=mode, epochs=epochs,
                reuse_preparation=(clean_user_path(prep) if prep else None))
            if res.get("status") == STATUS_INSUFFICIENT_SIGNAL:
                print(f"\n[중단] {res.get('reason_ko')}")
                print(f"  준비 단계 결과: {dumps(res.get('preparation'))[:1500]}")
                print(f"\n결과: {runner.run_dir}")
                return
            print(f"\n상태: {res['status']} / 학습 결과 판정: "
                  f"{res['learning_outcome']['verdict']}")
            if "theta_change" in res:
                tc = res["theta_change"]
                print(f"  theta 변화 평균 |Δθ| {tc['mean_abs_change_mV']:.6f} mV, "
                      f"최대 {tc['max_abs_change_mV']:.6f} mV, "
                      f"마스크 밖 변화 {tc['n_changed_outside_mask']}개")
                print(f"  준비 산출물 불변 {res['preparation_signatures_unchanged']}, "
                      f"고정 파라미터 불변 {res['fixed_parameters_unchanged']}")
            else:
                print(f"  P 변화 평균 |ΔP| {res['P_change']['mean_abs']:.6f}, "
                      f"고정 파라미터 불변 {res['fixed_parameters_unchanged']}")
            print(f"  test(교사 없음): {res['test'].get('status')} CE "
                  f"{res['test'].get('cross_entropy')} 정확도 "
                  f"{res['test'].get('accuracy')} (다수 기준선 "
                  f"{res['test'].get('majority_baseline')})")
            print(f"\n결과: {runner.run_dir}")
        elif choice == "6":
            epochs = int(_ask("조건마다 에폭 수", "1"))
            print(f"  기본 조건 목록: {', '.join(THRESHOLD_CONDITIONS)}")
            picked = _ask("비교할 조건 (쉼표 구분, 비우면 위 6개 전부)", "")
            conds = ([c.strip() for c in picked.split(",") if c.strip()]
                     if picked else None)
            res = run_comparison(cfg, out, self.device_choice, conditions=conds,
                                 epochs=epochs,
                                 progress=lambda m: print(f"  … {m}"))
            for cond, r in res["results"].items():
                print(f"  {cond:28s} 상태 {r.get('status'):10s} "
                      f"순방향 {r.get('forward_calls')} "
                      f"판정 {r.get('learning_outcome', {}).get('verdict')}")
            print(f"\n결과: {res['root']}")
        elif choice == "7":
            print("\n  넣을 것은 **파일이 아니라 실행 폴더**다. 메뉴 4(시뮬레이션)나 "
                  "5(학습)가 끝날 때 찍어 준 '결과: ...' 경로를 그대로 붙여넣어라.")
            print(f"  예) {out / 'simulate_20260920T012345Z_ab12cd34'}")
            print("  그 폴더 안에 manifest.json, resolved_config.json, "
                  "events.h5(또는 events_chunk*.npz) 가 있다.")
            self._show_recent_runs(out)
            rd = clean_user_path(_ask("조회할 실행 폴더"))
            nid = int(_ask("뉴런 ID", "0"))
            sample = _ask("sample_id (비우면 전체)", "")
            episode = _ask("episode_id (비우면 전체)", "")
            replica = _ask("replica_id (비우면 전체)", "")
            insp = NeuronInspector(rd)
            scope: dict[str, Any] = {}
            if sample:
                scope["sample_id"] = int(sample)
            if episode:
                scope["episode_id"] = int(episode)
            if replica:
                scope["replica_id"] = int(replica)
            tables = insp.available_tables()
            print("\n[이 폴더의 기록]")
            print(dumps(tables))
            if tables["events"]["rows"] == 0:
                print("  [알림] 이 폴더에는 입력 사건 행이 없다. recording.mode 가 "
                      "summary 였거나, 조회하려는 뉴런이 선택 목록에 없었을 수 있다. "
                      "아래 3x3 조회의 구조·메타데이터는 그대로 볼 수 있다.")
            res = insp.explain(nid, **scope)
            print(dumps({k: v for k, v in res.items() if k != "events"})[:3000])
            ts = res.get("threshold_state", {})
            if ts.get("status") != "completed":
                print(f"  [알림] {ts.get('reason_ko')}")
            else:
                print(f"  [임계값] 저장된 theta_eff {ts.get('theta_eff_at_last_row')} "
                      f"(base {ts.get('theta_base_mV')} + fast "
                      f"{ts.get('theta_fast_mV')})")
            cfg_run = read_json(rd / "resolved_config.json")
            env_dev = resolve_device(self.device_choice, self.env)
            t = require_torch()
            model = CorticalModel(cfg_run, env_dev,
                                  t.float32 if cfg_run["dtype"] == "float32" else t.float64,
                                  SeedStreams(int(cfg_run["seed"])))
            # 학습된 theta_base 가 저장되어 있으면 그것을 싣는다. 없으면 초기값
            # 상태라는 사실을 분명히 알리고 '학습 후' 라고 표시하지 않는다.
            theta_source = "초기값 (학습된 theta_base 를 찾지 못했다)"
            latest = CheckpointManager(rd).latest()
            if latest is not None:
                meta, tensors = CheckpointManager(rd).load(latest)
                if (str(meta.get("format"))
                        == "visual_cortex_gpu.threshold_checkpoint.v1"
                        and "theta_base" in tensors):
                    model.neurons.theta_base = t.tensor(
                        np.asarray(tensors["theta_base"], dtype=np.float64),
                        dtype=model.dtype, device=model.device)
                    theta_source = (f"체크포인트 {latest.name} 의 학습된 theta_base "
                                    f"(epoch {meta.get('epoch')}, "
                                    f"batch {meta.get('next_batch_index')})")
            print(f"\n[3x3 기록 인터페이스] theta_base 출처: {theta_source}")
            view = model.neuron_view(nid, run_id=rd.name, **scope)
            print(dumps(view.to_dict())[:3000])
        elif choice == "8":
            rd = clean_user_path(_ask("재개할 실행 폴더"))
            cfg_run = read_json(rd / "resolved_config.json")
            runner = ExperimentRunner(cfg_run, run_dir=rd,
                                      device_choice=self.device_choice, env=self.env)
            res = runner.run_resume()
            print(f"상태: {res['status']} / 조건 {res.get('mode')} / 판정 "
                  f"{res.get('learning_outcome', {}).get('verdict')}")
        elif choice == "9":
            print("\n  넣을 것은 **실행 폴더**다 (그 안의 figures 폴더가 아니다).")
            print("  메뉴 4·5·6 이 끝날 때 찍어 준 '결과: ...' 경로를 붙여넣어라.")
            self._show_recent_runs(out)
            rd = clean_user_path(_ask("보고서를 만들 실행 폴더"))
            builder = ReportBuilder(rd)
            if builder.resolve_note:
                print(f"  [알림] {builder.resolve_note}")
            path = builder.build()
            print(f"보고서: {path}")
            try:
                figs = make_figures(builder.dir)
                print(f"그림 {len(figs)}개:")
                for f in figs:
                    print(f"    - {f}")
            except RuntimeError as exc:
                print(f"[그림 생략] {exc}")
        elif choice == "10":
            runner = ExperimentRunner(cfg, output_root=out,
                                      device_choice=self.device_choice, env=self.env)
            res = runner.run_benchmark()
            for r in res["runs"]:
                print(f"  {r['device']:5s} 조립 {r['build_seconds']:6.2f}s  "
                      f"전처리 {r['preprocess_seconds']:6.3f}s  "
                      f"스텝당 {r['kernel_ms_per_step']:8.3f} ms "
                      f"({r['measurement_method']})")
            print(f"\n결과: {runner.run_dir}")
        elif choice == "11":
            self.inhibition_menu(cfg, out)
        elif choice == "12":
            print("  1. train 입력으로 전달 보정 (실제 GPU 엔진, 과제 학습 없음)")
            print("  2. 저장된 calibrated_config.json 불러오기")
            print("  3. 보정 해제: 원래 초기 연결 강도로 돌아가기")
            sub = _ask("선택 (0: 뒤로)", "0")
            if sub == "1":
                tc = cfg.get("transmission_calibration", transmission_calibration_defaults())
                print(f"  train 최대 {tc['fit_max_samples']}개, 연결군마다 배율 {tc['gain_grid']}.")
                print("  임계값 10·배선·억제 연결은 유지. 감각 흥분성 w0 초기값만 보정한다.")
                print("  성공을 보장하지 않는다. 수 분 이상 걸릴 수 있고 진행 기록을 저장한다.")
                if _ask("전달 보정을 실행할까? (y/n)", "n").lower() not in ("y", "yes"):
                    return
                result = run_transmission_calibration(cfg, out, self.device_choice)
                self.calibrated_cfg = load_transmission_config(Path(result["calibrated_config"]))
                self.preset = self.calibrated_cfg["meta"]["preset"]
                print(f"  상태 {result['status']}, 학습 진입 준비 {result['learning_ready']}")
                print("  채택한 연결 배율:", result["rule_gains"])
                print(f"  결과: {result['run_dir']}")
                print(f"  재사용 설정: {result['calibrated_config']}")
                print("  현재 세션에 보정 설정을 적용했다. 다음은 메뉴 11→1로 억제 진단.")
                if not result["learning_ready"]:
                    print("  전달/구별 조건 미달이다. 부분 보정 상태를 저장했으며 학습 성공을 뜻하지 않는다.")
            elif sub == "2":
                path = clean_user_path(_ask("calibrated_config.json 파일 경로"))
                self.calibrated_cfg = load_transmission_config(path)
                self.preset = self.calibrated_cfg["meta"]["preset"]
                print(f"  보정 설정 적용: {self.preset}, seed={self.calibrated_cfg['seed']}")
            elif sub == "3":
                self.calibrated_cfg = None
                print("  원래 초기 연결 강도를 사용한다.")
        elif choice == "13":
            self.wiring_menu(cfg, out)
        elif choice == "14":
            self.paired_menu(cfg, out)
        else:
            print(f"  '{choice}' 은(는) 없는 번호다. 0~14 중에서 고르라.")

    # ------------------------------------------------------------------
    def _base_cfg(self) -> dict[str, Any]:
        """메뉴 1~13 이 쓸 설정. 14-A 에서 고른 배선 모드·엔진을 적용한다."""
        if self.calibrated_cfg is not None:
            cal = copy.deepcopy(self.calibrated_cfg)
            # 불러온 보정 설정의 배선·엔진이 기준이다. 메뉴 표시도 그 값으로 맞춘다.
            self.wiring_mode = str(cal["paired"]["wiring_mode"])
            self.engine_kind = str(cal["engine_model"]["kind"])
            return cal
        if self.wiring_mode == "legacy" and self.engine_kind == ENGINE_KINDS[0]:
            return build_config(self.preset)
        return paired_config(self.preset, self.wiring_mode, engine_kind=self.engine_kind,
                             budget_mode=self.budget_mode)

    def _model_notice(self, cfg: dict[str, Any]) -> None:
        mode = cfg["paired"]["wiring_mode"]
        kind = cfg["engine_model"]["kind"]
        if mode != "legacy" or kind != ENGINE_KINDS[0]:
            print(f"  [알림] 이 작업은 새 모델을 사용한다: 배선 {mode}, 엔진 {kind}. "
                  f"기존 3.2.2 결과와 같은 모델이 아니다.")
            if mode != "legacy":
                print("         (메뉴 5/6/11 의 학습은 기존 L2/L3 교정 경로를 쓴다. 새 "
                      "이중 교정은 메뉴 14-D/E 에서 쓴다.)")

    def paired_menu(self, cfg: dict[str, Any], out: Path) -> None:
        """14번 하위 메뉴. 고른 작업만 실행한다."""
        while True:
            print(PAIRED_MENU_TEXT)
            print(f"  현재: preset={self.preset}, 배선={self.wiring_mode}, "
                  f"엔진={self.engine_kind}, 수렴 예산={self.budget_mode}")
            sub = _ask("하위 선택", "0").strip().upper()
            if sub in ("0", ""):
                return
            if sub == "A":
                print(f"  배선 모드: {list(PAIRED_WIRING_MODES)}")
                m = _ask("배선 모드", self.wiring_mode).strip()
                if m not in PAIRED_WIRING_MODES:
                    print(f"  '{m}' 은(는) 없는 모드다.")
                    continue
                print(f"  엔진: {list(ENGINE_KINDS)}")
                k = _ask("엔진", self.engine_kind).strip()
                if k not in ENGINE_KINDS:
                    print(f"  '{k}' 은(는) 없는 엔진이다.")
                    continue
                b = self.budget_mode
                if m == "eccentric_fanin":
                    print(f"  수렴 가중치 예산: {list(PAIRED_BUDGET_MODES)}")
                    b = _ask("예산", self.budget_mode).strip()
                    if b not in PAIRED_BUDGET_MODES:
                        print(f"  '{b}' 은(는) 없는 예산 방식이다.")
                        continue
                if self.calibrated_cfg is not None and (
                        m != self.calibrated_cfg["paired"]["wiring_mode"]
                        or k != self.calibrated_cfg["engine_model"]["kind"]):
                    print("  [알림] 불러온 전달 보정 설정은 그 배선·엔진 전용이다. 다른 "
                          "배선/엔진을 고르면 보정 설정을 해제한다 (다른 모델에 재사용하지 "
                          "않는다).")
                    self.calibrated_cfg = None
                self.wiring_mode, self.engine_kind, self.budget_mode = m, k, b
                cfg = self._base_cfg()
                print(f"  적용: 배선 {m}, 엔진 {k}, 예산 {b}. 이후 메뉴 1~14 에 적용된다.")
                continue
            cfg = self._base_cfg()
            need_paired = sub in ("B", "D", "E")
            if need_paired and cfg["paired"]["wiring_mode"] == "legacy":
                print("  이 작업은 대응 배선이 필요하다. 먼저 A 에서 paired_only 또는 "
                      "eccentric_fanin 을 고르라.")
                continue
            self._model_notice(cfg)
            if sub == "B":
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice, env=self.env)
                res = runner.run_paired_contract()
                print(f"\n  계약 판정: {res['status']}")
                for p in res.get("problems", []):
                    print(f"    - {p}")
                for area, d in res.get("disconnected", {}).items():
                    print(f"    {area:4s} L2무입력 {d['L2_without_L4_input']} / "
                          f"L2·L3 짝없음 {d['unpaired_L2_or_L3']} / "
                          f"L3무출력 {d['L3_without_next_L4_output']} / "
                          f"L4 L2미연결 {d['L4_not_routed_to_L2']}")
                for k2, v in res.get("interareal", {}).items():
                    print(f"    {k2:10s} {v['correspondence']:12s} "
                          f"L3 {v['n_src_slots']} -> L4 {v['n_dst_slots']}")
                print(f"\n결과: {runner.run_dir}")
            elif sub == "C":
                names = [n for n in dir(ValidationSuite) if n.startswith("check_")
                         and "_paired_P" in n]
                res = run_validation(cfg, out, self.device_choice, only=names,
                                     progress=lambda msg: print(f"  … {msg}"))
                for c in res["checks"]:
                    if c["status"] != STATUS_NOT_RUN:
                        print(f"  [{c['status']:>19s}] {c['name']}")
                print(f"  통과 {res['n_passed']} / 실패 {res['n_failed']} / "
                      f"측정만 {res['n_measured']} / 미실행(선택 안 함) {res['n_not_run']}")
                print(f"\n결과: {res['run_dir']}")
            elif sub == "D":
                print(f"  조건: {list(PAIRED_CONDITIONS)}")
                cond = _ask("조건", "sequential_dual").strip()
                if cond not in PAIRED_CONDITIONS:
                    print(f"  '{cond}' 은(는) 없는 조건이다.")
                    continue
                epochs = int(_ask("에폭 수", str(cfg["training"]["epochs"])))
                prep = _ask("재사용할 대응 모델 준비 파일 (비우면 새로 준비)", "")
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice, env=self.env)
                res = runner.run_paired_train(
                    condition=cond, epochs=epochs,
                    reuse_preparation=clean_user_path(prep) if prep else None)
                print(f"\n  상태 {res['status']} / 판정 "
                      f"{res.get('learning_outcome', {}).get('verdict')}")
                if "test" in res:
                    print(f"  test(교사 없음): {res['test'].get('status')} 정확도 "
                          f"{res['test'].get('accuracy')} CE {res['test'].get('cross_entropy')}")
                print(f"\n결과: {runner.run_dir}")
            elif sub == "E":
                print(f"  조건 목록: {', '.join(PAIRED_CONDITIONS)}")
                picked = _ask("비교할 조건 (쉼표, 비우면 전부)", "")
                conds = [c.strip() for c in picked.split(",") if c.strip()] or None
                seeds_raw = _ask("시드 (쉼표, 비우면 현재 시드 하나)", "")
                seeds = ([int(x) for x in seeds_raw.split(",") if x.strip()]
                         if seeds_raw else None)
                epochs = int(_ask("조건마다 에폭 수", "1"))
                res = run_paired_compare(cfg, out, self.device_choice, conds, seeds=seeds,
                                         epochs=epochs,
                                         progress=lambda msg: print(f"  … {msg}"))
                for key, r in res["results"].items():
                    print(f"  {key:32s} {r.get('status')} test "
                          f"{r.get('test', {}).get('accuracy')}")
                print(f"\n결과: {res['root']}")
            elif sub == "F":
                modes_raw = _ask("비교할 배선 (쉼표)", "legacy,paired_only,eccentric_fanin")
                modes = [m.strip() for m in modes_raw.split(",") if m.strip()]
                bad = [m for m in modes if m not in PAIRED_WIRING_MODES]
                if bad:
                    print(f"  없는 배선 모드: {bad}")
                    continue
                bm_raw = _ask("수렴 예산 (쉼표)", "summed,fixed_total_budget")
                bms = [b.strip() for b in bm_raw.split(",") if b.strip()]
                res = run_wiring_mode_compare(cfg, out, self.device_choice, modes=modes,
                                              budget_modes=bms,
                                              progress=lambda msg: print(f"  … {msg}"))
                for tag, r in res["results"].items():
                    if r.get("status") != "completed":
                        print(f"  {tag:32s} 실패: {r.get('error')}")
                        continue
                    rows = r["stimuli"]["diag_ori_00"]
                    ff = rows[0]["first_failure_point"] if rows else None
                    print(f"  {tag:32s} 첫 실패 지점 {ff}")
                print(f"\n결과: {res['root']}")
            elif sub == "G":
                print("  메뉴 11-1 (억제 진단) 을 현재 배선으로 실행한다.")
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice, env=self.env)
                res = runner.run_inhibition_scan()
                print(f"  상태 {res.get('status')} {res.get('reason', '')}")
                print(f"\n결과: {runner.run_dir}")
            elif sub == "H":
                res = run_engine_cost_compare(cfg, out, self.device_choice,
                                              progress=lambda msg: print(f"  … {msg}"))
                for kind, r in res["results"].items():
                    print(f"  {kind:32s} {r.get('status')} 순수 "
                          f"{r.get('pure_engine_median_s')} s / 출처기록 "
                          f"{r.get('with_provenance_median_s')} s")
                print(f"\n결과: {res['root']}")
            elif sub == "I":
                self._show_recent_runs(out)
                rd = clean_user_path(_ask("보고서를 만들 실행 폴더"))
                builder = ReportBuilder(rd)
                if builder.resolve_note:
                    print(f"  [알림] {builder.resolve_note}")
                print(f"보고서: {builder.build()}")
                try:
                    for f in make_figures(builder.dir):
                        print(f"    - {f}")
                except RuntimeError as exc:
                    print(f"[그림 생략] {exc}")
            elif sub == "J":
                rows = paired_implementation_table()
                for r in rows:
                    print(f"  [{r['where']:>22s}] {r['function']}")
                rd = new_run_dir(out, "implementation_table")
                write_json(rd / "paired_implementation_table.json",
                           {"rows": rows, "version": __version__})
                _write_rows_csv(rd / "implementation_table.csv", rows)
                print(f"\n저장: {rd}")
            elif sub == "K":
                self._paired_sweep_menu(cfg, out)
            else:
                print(f"  '{sub}' 은(는) 없는 선택이다. A~K 또는 0 을 고르라.")

    def _paired_sweep_menu(self, cfg: dict[str, Any], out: Path) -> None:
        """14-K: 모든 신규 테스트를 조합해 자동으로 실행한다."""
        print("\n  [전체 자동 조합 실행]")
        print("  순서: 사전 검사 P1~P16 -> 배선별 연결 계약 -> 전달 비교 -> 엔진 비용 -> "
              "억제 진단 -> 교정 학습 전체 조합 -> 요약·보고서·그림")
        print("  이 작업은 현재 preset/seed/학습 설정을 바탕으로 배선·엔진·투영·gate·조건·"
              "시드를 스스로 조합한다 (14-A 의 배선 선택과 무관).")
        resume = _ask("이어서 실행할 조합 폴더 (비우면 새로 시작)", "")
        if resume:
            rd = clean_user_path(resume)
            if not (rd / "sweep_plan.json").is_file():
                print(f"  조합 실행 폴더가 아니다 (sweep_plan.json 없음): {rd}")
                return
            plan = read_json(rd / "sweep_plan.json")
            left = len({c["effective_key"] for c in plan["cells"]})
            print(f"  수준 {plan['level']}, 학습 칸 {left}개 중 끝난 칸은 건너뛴다.")
            res = run_full_sweep(cfg, None, self.device_choice, resume_dir=rd,
                                 progress=lambda m: print(f"  … {m}"))
        else:
            for name, lv in SWEEP_LEVELS.items():
                p = plan_sweep(cfg, name)
                print(f"    {name:9s} 학습 칸 {p['n_cells_total']:5d}개 (실제 계산 "
                      f"{p['n_cells_executed']}개, 결과 공유 {p['n_cells_shared']}개), "
                      f"단계 {len(p['stages'])}개 - {lv['note_ko']}")
            level = _ask("조합 수준 quick / standard / full", "standard").strip()
            if level not in SWEEP_LEVELS:
                print(f"  '{level}' 은(는) 없는 수준이다.")
                return
            raw_seeds = _ask("시드 목록 (쉼표, 비우면 수준 기본값)", "")
            seeds = ([int(x) for x in raw_seeds.split(",") if x.strip()]
                     if raw_seeds else None)
            raw_ep = _ask("학습 칸마다 에폭 수 (비우면 수준 기본값)", "")
            plan = plan_sweep(cfg, level, seeds=seeds,
                              epochs=int(raw_ep) if raw_ep else None)
            lv = plan["level_definition"]
            print(f"\n  계획: 배선 {[w for w, _ in lv['wiring']]} x 엔진 {lv['engines']} x "
                  f"투영 {lv['projections']} x gate {lv['gate_rules']} x 조건 "
                  f"{len(plan['conditions'])} x 시드 {plan['seeds']}")
            print(f"  학습 칸 {plan['n_cells_total']}개 -> 실제 계산 {plan['n_cells_executed']}"
                  f"개 (같을 수밖에 없는 {plan['n_cells_shared']}개는 결과 공유), 에폭 "
                  f"{plan['epochs']}, 학습 표본 상한 {plan['max_samples'] or '없음'}")
            print(f"  {plan['sharing_rule_ko']}")
            print(f"  {plan['selection_rule_ko']}")
            print("  실행 시간은 실행 중 측정한 칸 평균으로만 추정해 보여 준다. Ctrl+C 로 "
                  "멈추면 같은 폴더를 넣어 이어서 실행할 수 있다.")
            if level == "full":
                if _ask("full 은 매우 오래 걸린다. 진행하려면 yes 입력", "").strip() != "yes":
                    print("  취소했다.")
                    return
            elif _ask("시작할까? (y/N)", "N").strip().lower() not in ("y", "yes"):
                print("  취소했다.")
                return
            stop = _ask("사전 검사가 실패하면 학습 칸을 건너뛸까? (y/N)", "N").strip().lower()
            res = run_full_sweep(cfg, out, self.device_choice, level=level, seeds=seeds,
                                 epochs=int(raw_ep) if raw_ep else None,
                                 stop_on_precheck_failure=stop in ("y", "yes"),
                                 progress=lambda m: print(f"  … {m}"))
        print(f"\n  상태 {res['status']} {res.get('reason', '')}")
        print(f"  학습 칸 상태: {res['cell_status_counts']}")
        for st in res["stages"]:
            print(f"    [{st['status']:>19s}] {st['stage_id']}")
        for cond, ch in res.get("dev_based_choice", {}).items():
            print(f"    dev 기준 {cond:26s}: {ch['wiring']}/{ch['engine']}/"
                  f"{ch['projection']}/{ch['gate_rule']} dev CE "
                  f"{_fmt_opt(ch['dev_ce_last_mean'])}")
        print(f"\n결과: {res['root']}")
        print("  요약: sweep_summary.csv (칸별), sweep_aggregate.csv (시드 평균), report_ko.md")

    # ------------------------------------------------------------------
    def wiring_menu(self, cfg: dict[str, Any], out: Path) -> None:
        """13번 하위 메뉴 (A~F). 고른 작업만 수행한다."""
        wb = cfg["wiring_balance"]
        while True:
            print(WIRING_MENU_TEXT)
            groups = list(wb["target_groups"] or wb["preferred_groups"])
            n_stim = 3 + min(6, len(cfg["decoder"]["classes"])) + 2
            print(f"  현재 설정: preset={self.preset}, seed={cfg['seed']}, "
                  f"자극 {cfg['engine']['sample_ms']} ms / dt "
                  f"{cfg['engine']['dt_ms']} ms")
            profile_status = transmission_profile_status(cfg)
            print(f"  전달 보정: {profile_status['note_ko']}")
            if profile_status["loaded"]:
                print(f"  보정 시드: {profile_status['fit_seed']} / "
                      f"연결군별 배율: {profile_status['rule_gains']}")
            else:
                print("  이전 전달 보정 결과를 사용하려면 F에서 calibrated_config.json을 불러온다.")
            print(f"  대상 연결군 후보: {groups}")
            print(f"  조건: {list(wb['conditions'])}")
            print(f"  억제 gain: 기본 {wb['inhibition_gain']} / "
                  f"보조 {wb['aux_inhibition_gain']} (두 gain 을 섞지 않는다)")
            print(f"  다중 시드 기본 후보: {list(wb['seeds'])}")
            print(f"  진단 자극 약 {n_stim}개 (무입력·균일 영상 포함, 통제용)")
            sub = _ask("A/B/C/D/E/F 중 선택 (0=뒤로)", "0").strip().upper()
            if sub in ("0", ""):
                return
            if sub == "F":
                path = clean_user_path(_ask("calibrated_config.json 경로"))
                try:
                    loaded = load_transmission_config(path)
                except (OSError, ValueError, KeyError) as exc:
                    print(f"  [설정 오류] {exc}")
                    continue
                self.calibrated_cfg = loaded
                self.preset = str(loaded["meta"]["preset"])
                cfg = copy.deepcopy(loaded)
                wb = cfg["wiring_balance"]
                print(f"  보정 설정 적용: {self.preset}, seed={cfg['seed']}")
                continue
            if sub == "A":
                raw = _ask("연결군 (쉼표 구분, 비우면 후보 전체)", "")
                sel = ([x.strip() for x in raw.split(",") if x.strip()]
                       if raw else None)
                g = self._ask_wiring_gain(wb)
                print(f"  [예상 작업량] 자극 {n_stim}개 x 1 조건 = 약 {n_stim} 회의 "
                      f"{cfg['engine']['sample_ms']} ms 순방향 실행. 학습 없음.")
                print(f"  [예상 저장량] neuron_input_metrics.csv 약 "
                      f"{n_stim * 40 * len(sel or groups)} 행 내외 + 구조 진단 JSON")
                if not self._confirm():
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_wiring_diagnose(groups=sel, inhibition_gain=g)
                self._print_wiring_structure(res["structure"])
                print(f"\n결과: {runner.run_dir}")
            elif sub == "B":
                nm = _ask("대상 연결군 하나", groups[0] if groups else "")
                if not nm:
                    print("  연결군 이름이 필요하다.")
                    continue
                raw = _ask("시드 목록 (쉼표 구분, 비우면 현재 시드 하나)", "")
                seeds = (_parse_int_list(raw, name="시드 목록") if raw
                         else [int(cfg["seed"])])
                try:
                    validate_wiring_seeds(cfg, seeds)
                except ValueError as exc:
                    print(f"  [설정 오류] {exc}")
                    continue
                g = self._ask_wiring_gain(wb)
                n_c = len(wb["conditions"])
                print(f"  [예상 작업량] 시드 {len(seeds)}개 x 조건 {n_c}개 x 자극 "
                      f"{n_stim}개 = 약 {len(seeds) * n_c * n_stim} 회 순방향 실행")
                if len(seeds) < 2:
                    print("  [알림] 단일 시드는 탐색용이다. 소수 시드로 일반적인 "
                          "결론을 주장하지 않는다.")
                if not self._confirm():
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_wiring_compare(group_name=nm, seeds=seeds,
                                                inhibition_gain=g)
                self._print_wiring_paired(res)
                print(f"\n결과: {res['root']}")
            elif sub == "C":
                raw = _ask("연결군 목록 (쉼표 구분, 비우면 후보 전체)", "")
                sel = ([x.strip() for x in raw.split(",") if x.strip()]
                       if raw else None)
                raw2 = _ask("시드 목록 (쉼표 구분, 비우면 현재 시드 하나)", "")
                seeds = (_parse_int_list(raw2, name="시드 목록") if raw2
                         else [int(cfg["seed"])])
                try:
                    validate_wiring_seeds(cfg, seeds)
                except ValueError as exc:
                    print(f"  [설정 오류] {exc}")
                    continue
                g = self._ask_wiring_gain(wb)
                n_g = len(sel or groups)
                n_c = len(wb["conditions"])
                print(f"  [예상 작업량] 연결군 {n_g}개 x 시드 {len(seeds)}개 x 조건 "
                      f"{n_c}개 x 자극 {n_stim}개 = 약 "
                      f"{n_g * len(seeds) * n_c * n_stim} 회 순방향 실행")
                print("  연결군을 하나씩만 바꾼다. 앞 변경을 다음 조건에 누적하지 "
                      "않는다.")
                if not self._confirm():
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_wiring_bundle(groups=sel, seeds=seeds,
                                               inhibition_gain=g)
                for nm, row in res["per_group"].items():
                    print(f"  {nm:<16s} 상태 {row.get('status', 'completed')}")
                if res["failures"]:
                    print(f"  [알림] 실패한 연결군 {len(res['failures'])}개를 표에서 "
                          f"빼지 않고 남겼다.")
                print(f"\n결과: {res['root']}")
            elif sub == "D":
                print("  [예상 작업량] tiny preset 으로 T1~T12 검사만 실행한다 "
                      "(학습·본 실험 없음).")
                if not self._confirm():
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_wiring_integrity()
                for c in res["checks"]:
                    if c["status"] == STATUS_NOT_RUN:
                        continue
                    print(f"    [{c['status']:>15s}] {c['name']}")
                print(f"  통과 {res['n_passed']} / 실패 {res['n_failed']} / "
                      f"해당없음 {res['n_not_applicable']}")
                print(f"\n결과: {runner.run_dir}")
            elif sub == "E":
                print("\n  넣을 것은 **실행 폴더**다 (그 안의 figures 폴더가 아니다).")
                self._show_recent_runs(out)
                rd = clean_user_path(_ask("보고서를 만들 실행 폴더"))
                builder = ReportBuilder(rd)
                if builder.resolve_note:
                    print(f"  [알림] {builder.resolve_note}")
                path = builder.build()
                print(f"보고서: {path}")
                try:
                    figs = make_figures(builder.dir)
                    print(f"그림 {len(figs)}개:")
                    for f in figs:
                        print(f"    - {f}")
                except RuntimeError as exc:
                    print(f"[그림 생략] {exc}")
            else:
                print(f"  '{sub}' 은(는) 없는 선택이다. A/B/C/D/E/F 또는 0 을 고르라.")

    @staticmethod
    def _confirm() -> bool:
        return _ask("실행할까? (y/n)", "n").strip().lower() in ("y", "yes")

    @staticmethod
    def _ask_wiring_gain(wb: dict[str, Any]) -> float:
        raw = _ask(f"억제 gain ({wb['inhibition_gain']}=기본, "
                   f"{wb['aux_inhibition_gain']}=보조)",
                   str(wb["inhibition_gain"]))
        try:
            g = float(raw)
        except ValueError:
            print(f"  숫자가 아니다: {raw!r} -> 기본값을 쓴다.")
            return float(wb["inhibition_gain"])
        if not (INHIBITION_GAIN_MIN <= g <= INHIBITION_GAIN_MAX):
            print(f"  [0, 1] 범위가 아니다: {g} -> 기본값을 쓴다.")
            return float(wb["inhibition_gain"])
        if g != float(wb["inhibition_gain"]):
            print("  [알림] 기본 gain 과 다른 값이다. 두 gain 의 결과를 하나로 섞지 "
                  "마라. 억제를 끈 조건만으로 정상 회로의 개선을 주장하지 마라.")
        return g

    @staticmethod
    def _print_wiring_structure(structure: dict[str, Any]) -> None:
        print("\n  [구조 진단] 연결군별 (후보 수신 / 연결 없는 수신 / in_degree "
              "CV / 가중치합 CV)")
        for r in structure.get("groups", []):
            if r.get("status") == "empty":
                print(f"    {r['group']:<16s} 비어 있음 ({r['empty_reason']})")
                continue
            idg, ws = r["in_degree"], r["input_weight_sum_nS"]
            print(f"    {r['group']:<16s} dst={r['n_dst_candidates']:<4d} "
                  f"no_input={r['n_dst_without_input']:<4d} "
                  f"in_cv={_fmt_opt(idg['cv'])} w_cv={_fmt_opt(ws['cv'])} "
                  f"in_gini={_fmt_opt(idg['gini'])}")
        for r in structure.get("bypass_groups", []):
            print(f"    [우회] {r['group']}")
        if structure.get("missing_groups"):
            print(f"    [없음] {[g['group'] for g in structure['missing_groups']]}")
        print("  쏠림 지표가 높다는 이유만으로 결함이라고 판정하지 않는다 "
              "(정상적인 선택성일 수 있다).")

    @staticmethod
    def _print_wiring_paired(res: dict[str, Any]) -> None:
        print(f"\n  [짝지은 비교] 연결군 {res.get('group')} / "
              f"억제 gain {res.get('inhibition_gain')}")
        for cond, row in (res.get("paired", {}).get("by_condition", {})).items():
            if row.get("n_seeds", 0) == 0:
                print(f"    {cond:<24s} 자료 없음")
                continue
            d = row["delta_delivered_fraction"]
            sp = row["delta_fraction_spiked"]
            print(f"    {cond:<24s} 시드 {row['n_seeds']} | "
                  f"Δ전달비율 {_fmt_opt(d['mean'])}±{_fmt_opt(d['std'])} | "
                  f"Δ발화비율 {_fmt_opt(sp['mean'])}±{_fmt_opt(sp['std'])}")
        print("  흥분성 입력 증가·발화 증가·도형 구별 가능성·분류 정확도는 서로 "
              "다른 결과다.")

    # ------------------------------------------------------------------
    def inhibition_menu(self, cfg: dict[str, Any], out: Path) -> None:
        """11번 하위 메뉴. 고른 작업만 수행하고 자동으로 학습을 시작하지 않는다."""
        sched = InhibitionSchedule.from_config(cfg)
        n_cortex = sum(1 for v in cfg["areas"].values() if v["kind"] == "cortex")
        while True:
            print(INHIBITION_MENU_TEXT)
            print(f"  현재 설정: preset={self.preset} "
                  f"({n_cortex}개 피질 영역), "
                  f"자극 {cfg['engine']['sample_ms']} ms / "
                  f"dt {cfg['engine']['dt_ms']} ms")
            print(f"  스케줄: start={sched.start} -> end={sched.end}, "
                  f"warmup {sched.warmup_epochs} + ramp {sched.ramp_epochs} + "
                  f"hold {sched.hold_epochs} = 총 {sched.total_epochs} 에폭 "
                  f"({sched.kind})")
            print(f"  진단 배율 목록: {cfg['inhibition']['scan_values']}")
            sub = _ask("번호를 선택하라", "0")
            if sub == "0":
                return
            if sub == "1":
                raw = _ask("검사할 배율 목록 (쉼표 구분, 비우면 기본값)", "")
                vals = (_parse_float_list(raw, name="배율 목록") if raw else None)
                n_v = len(vals or cfg["inhibition"]["scan_values"])
                n_s = 3 + min(6, len(cfg["decoder"]["classes"])) + 2
                print(f"  [예상 작업량] 배율 {n_v}개 x 자극 약 {n_s}개 "
                      f"(+반복 1회) = 약 {n_v * (n_s + 1)} 회의 "
                      f"{cfg['engine']['sample_ms']} ms 순방향 실행. 학습은 없다.")
                if _ask("실행할까? (y/n)", "n").lower() not in ("y", "yes"):
                    print("  취소했다.")
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_inhibition_scan(values=vals)
                print(f"\n상태: {res['status']} {res.get('reason','')}")
                print("  배율별 판정 (전달 / IT구별 / 무입력 / 포화 / 종합):")
                for r in res["summary"]["per_value"]:
                    print(f"    alpha={r['inhibition_gain']:<6} "
                          f"{str(r['transmits']):<5} "
                          f"{str(r['it_distinguishable']):<5} "
                          f"{str(r['blank_response_ok']):<5} "
                          f"{str(r['saturation_ok']):<5} -> "
                          f"{'사용 가능' if r['usable'] else '사용 불가'}")
                low = res["summary"]["lowest_usable_gain"]
                print(f"  학습에 쓸 수 있는 가장 낮은 배율: {low}")
                bn = res["summary"].get("zero_gain_bottleneck")
                if bn:
                    print("  [알림] 배율 0 에서도 전달되지 않는다. 억제를 더 줄여도 "
                          "해결되지 않는다 (이미 0 이다).")
                    for c in bn["candidate_causes_ko"]:
                        print(f"    - 잔여 병목 후보: {c}")
                print(f"\n결과: {runner.run_dir}")
            elif sub == "2":
                print(f"  조건: {', '.join(INHIBITION_CONDITIONS)} "
                      f"(선택: {', '.join(INHIBITION_OPTIONAL_CONDITIONS)})")
                cond = _ask("조건", "ramp_local")
                allowed = INHIBITION_CONDITIONS + INHIBITION_OPTIONAL_CONDITIONS
                if cond not in allowed:
                    print(f"  '{cond}' 는 없는 조건이다.")
                    continue
                bs = int(cfg["training"]["batch_size"])
                n_tr = (int(cfg["data"]["n_base_per_class"])
                        * int(cfg["data"]["n_variants"])
                        * len(cfg["decoder"]["classes"]))
                n_b = max(1, math.ceil(n_tr * 0.6 / bs))
                per_ep = n_b * (2 + int(cfg["threshold_learning"]["K_rounds"]))
                print(f"  [예상 작업량] {sched.total_epochs} 에폭 x 약 {n_b} 배치 "
                      f"x (자유 1 + round {cfg['threshold_learning']['K_rounds']} "
                      f"+ 사후 1) = 약 {sched.total_epochs * per_ep} 회의 "
                      f"{cfg['engine']['sample_ms']} ms 순방향 실행 + 준비 단계")
                print("  준비 단계는 이 학습 작업 안에서 수행된다. 다른 메뉴에서 "
                      "자동으로 이어지지 않는다.")
                if _ask("실행할까? (y/n)", "n").lower() not in ("y", "yes"):
                    print("  취소했다.")
                    continue
                runner = ExperimentRunner(cfg, output_root=out,
                                          device_choice=self.device_choice,
                                          env=self.env)
                res = runner.run_inhibition_train(condition=cond)
                self._print_inhibition_train_result(res)
                print(f"\n결과: {runner.run_dir}")
            elif sub == "3":
                print(f"  필수 네 조건: {', '.join(INHIBITION_CONDITIONS)}")
                raw = _ask("시드 목록 (쉼표 구분, 비우면 현재 시드 하나)", "")
                seed_list = (_parse_int_list(raw, name="시드 목록") if raw
                             else [int(cfg["seed"])])
                if len(seed_list) < 2:
                    print("  [알림] 단일 시드 실행은 탐색용이다. 단일 시드 개선을 "
                          "일반적인 성공으로 결론 내리지 않는다.")
                print(f"  [예상 작업량] 시드 {len(seed_list)}개 x 조건 4개 x "
                      f"{sched.total_epochs} 에폭. 준비는 시드당 한 번만 한다.")
                if _ask("실행할까? (y/n)", "n").lower() not in ("y", "yes"):
                    print("  취소했다.")
                    continue
                res = run_inhibition_compare(
                    cfg, out, self.device_choice, seeds=seed_list,
                    progress=lambda m: print(f"  … {m}"))
                for name, row in res["paired_differences"]["per_pair"].items():
                    print(f"  {name}: 평균 정확도 차이 "
                          f"{row['mean_delta_accuracy']} "
                          f"(시드 {row['n_usable_seeds']}개) — "
                          f"{row['description_ko']}")
                if res["failures"]:
                    print(f"  [알림] 실패한 조건 {len(res['failures'])}개를 표에서 "
                          f"빼지 않고 null 과 이유로 남겼다:")
                    for f in res["failures"]:
                        print(f"    - 시드 {f['seed']} / {f['condition']}: "
                              f"{f['error']}")
                print(f"\n결과: {res['root']}")
            else:
                print(f"  '{sub}' 은(는) 없는 번호다. 0~3 중에서 고르라.")

    @staticmethod
    def _print_inhibition_train_result(res: dict[str, Any]) -> None:
        if res.get("status") == STATUS_INSUFFICIENT_SIGNAL:
            print(f"\n[중단] {res.get('reason_ko')}")
            print(f"  중단 지점: {res.get('stopped_at')} "
                  f"(배율 {res.get('inhibition_gain')})")
            d = res.get("diagnosis") or {}
            for key in ("transmits", "it_distinguishable", "blank_response_ok",
                        "saturation_ok"):
                v = d.get(key)
                if isinstance(v, dict):
                    print(f"  {key}: {v.get('pass')}")
            print(f"  {res.get('not_run_ko','')}")
            return
        print(f"\n상태: {res['status']} / 조건 {res['condition']}")
        sch = res["schedule"]
        print(f"  스케줄: {sch['start']} -> {sch['end']} "
              f"({sch['kind']}, 총 {sch['total_epochs']} 에폭), "
              f"준비 배율 {res.get('prepared_at_inhibition_gain')}")
        print(f"  준비 산출물 불변: {res.get('preparation_signatures_unchanged')}")
        tc = res.get("theta_change") or {}
        print(f"  theta 변화 평균 |Δθ| {tc.get('mean_abs_change_mV')} mV, "
              f"마스크 밖 변화 {tc.get('n_changed_outside_mask')}개")
        test = res.get("test") or {}
        print(f"  최종 시험(배율 {res.get('final_eval_gain')}, 교사 없음): "
              f"상태 {test.get('status')} CE {test.get('cross_entropy')} "
              f"정확도 {test.get('accuracy')}")
        lo = res.get("learning_outcome") or {}
        print(f"  dev CE: start 배율 {lo.get('dev_ce_at_start_gain')} / "
              f"end 배율 {lo.get('dev_ce_at_end_gain')}")
        print("  '억제를 줄여 살아났다' / '교정이 도움이 됐다' / '정상 억제로 "
              "복원한 뒤에도 유지됐다' 는 서로 다른 결론이다.")


